 17	export interface ServerConfig {
 18	  readonly nodeEnv: 'development' | 'test' | 'production';
 19	  readonly port: number;
 20	  readonly guestSecret: string;
 21	  readonly corsOrigins: readonly string[];
 22	  readonly redisUrl?: string;
 23	  readonly redisPrefix: string;
 24	  readonly databaseUrl?: string;
 25	}
 26	
 27	export function loadConfig(environment: NodeJS.ProcessEnv = process.env): ServerConfig {
 28	  const parsed = environmentSchema.parse(environment);
 29	  if (parsed.NODE_ENV === 'production') {
 30	    if (parsed.GUEST_SECRET.startsWith('development-only')) {
 31	      throw new Error('PRODUCTION_GUEST_SECRET_REQUIRED');
 32	    }
 33	    if (!parsed.REDIS_URL) throw new Error('PRODUCTION_REDIS_URL_REQUIRED');
 34	    if (!parsed.DATABASE_URL) throw new Error('PRODUCTION_DATABASE_URL_REQUIRED');
 35	  }
 36	  return {
 37	    nodeEnv: parsed.NODE_ENV,
 38	    port: parsed.PORT,
 39	    guestSecret: parsed.GUEST_SECRET,
 40	    corsOrigins: parsed.CORS_ORIGINS.split(',')
 41	      .map((origin) => origin.trim())
 42	      .filter(Boolean),
 43	    ...(parsed.REDIS_URL ? { redisUrl: parsed.REDIS_URL } : {}),
 44	    redisPrefix: parsed.REDIS_PREFIX,
 45	    ...(parsed.DATABASE_URL ? { databaseUrl: parsed.DATABASE_URL } : {}),
 46	  };
 47	}
