 36	export interface RunningPokeWarServer extends PokeWarServer {
 37	  closeInfrastructure(): Promise<void>;
 38	}
 39	
 40	export async function bootstrapServer(config: ServerConfig): Promise<RunningPokeWarServer> {
 41	  let redis: RedisClients | null = null;
 42	  let identities: GuestIdentityStore = new MemoryGuestIdentityStore();
 43	  let roomStore: RoomStore = new MemoryRoomStore();
 44	  let deadlines: DeadlineStore = new MemoryDeadlineStore();
 45	  let roomLock: RoomLockAdapter = new RoomLock();
 46	  let memberships: RoomMembershipStore = new MemoryRoomMembershipStore();
 47	  let replays: ReplayRepository = new NullReplayRepository();
 48	  let accounts: AccountRepository = new MemoryAccountRepository();
 49	  let loginRateLimit: LoginRateLimit = new MemoryLoginRateLimit();
 50	  let ratings: RatingRepository = new MemoryRatingRepository();
 51	  let matchmakingStore: MatchmakingStore = new MemoryMatchmakingStore();
 52	  let stopReplayCleanup: () => void = () => undefined;
 53	
 54	  if (config.redisUrl) {
 55	    redis = await createRedisClients(config.redisUrl);
 56	    identities = new RedisGuestIdentityStore(redis.command, config.redisPrefix);
 57	    roomStore = new RedisIndexedRoomStore(redis.command, config.redisPrefix);
 58	    deadlines = new RedisDeadlineStore(redis.command, config.redisPrefix);
 59	    roomLock = new RedisRoomLock(redis.command, config.redisPrefix);
 60	    memberships = new RedisRoomMembershipStore(redis.command, config.redisPrefix);
 61	    loginRateLimit = new RedisLoginRateLimit(redis.command, config.redisPrefix);
 62	    matchmakingStore = new RedisMatchmakingStore(redis.command, config.redisPrefix);
 63	  }
 64	  if (config.databaseUrl) {
 65	    replays = new PostgresReplayRepository(new Pool({ connectionString: config.databaseUrl }));
 66	    accounts = new PostgresAccountRepository(new Pool({ connectionString: config.databaseUrl }));
 67	    ratings = new PostgresRatingRepository(new Pool({ connectionString: config.databaseUrl }));
 68	    stopReplayCleanup = startReplayCleanup(replays);
 69	  }
 70	
 71	  if (!redis) roomStore = new IndexedRoomStore(roomStore, deadlines);
 72	  const server = createPokeWarServer(config, {
 73	    identities,
 74	    roomStore,
 75	    roomLock,
 76	    replays,
 77	    memberships,
 78	    accounts,
 79	    loginRateLimit,
 80	    ratings,
 81	    matchmakingStore,
 82	    matchmakingLock: roomLock,
 83	    storageName: redis ? 'redis' : 'memory',
 84	  });
 85	  if (redis) server.io.adapter(createAdapter(redis.publisher, redis.subscriber));
 86	  const bots = new BotService(server.rooms);
 87	  const deadlineWorker = startDeadlineWorker(deadlines, server.rooms, {
 88	    onRoomUpdated: (room) => {
 89	      broadcastRoom(server.io, room);
 90	      void bots.executeBotSequence(room.id, (updated) => broadcastRoom(server.io, updated));
 91	    },
 92	  });
 93	  const stopMatchmakingWorker = startMatchmakingWorker(server.matchmaking, {
 94	    onUpdates: (updates) => broadcastMatchmaking(server.io, updates),
 95	    onRoom: (room) => broadcastRoom(server.io, room),
 96	  });
 97	
 98	  return {
 99	    ...server,
100	    async closeInfrastructure() {
101	      deadlineWorker.stop();
102	      stopMatchmakingWorker();
103	      stopReplayCleanup();
104	      await Promise.all([
105	        deadlines.close(),
106	        replays.close(),
107	        accounts.close(),
108	        ratings.close(),
109	        matchmakingStore.close(),
110	        redis?.close() ?? Promise.resolve(),
111	      ]);
112	    },
113	  };
114	}
  1	import { bootstrapServer } from './bootstrap.js';
  2	import { loadConfig } from './config/config.js';
  3	
  4	const config = loadConfig();
  5	const server = await bootstrapServer(config);
  6	
  7	server.httpServer.listen(config.port, () => {
  8	  console.log(`[server] PokeWar listening on http://localhost:${String(config.port)}`);
  9	});
