 11	async function shutdown(signal: string): Promise<void> {
 12	  console.log(`[server] received ${signal}, shutting down`);
 13	  await server.io.close();
 14	  if (server.httpServer.listening) {
 15	    await new Promise<void>((resolve, reject) => {
 16	      server.httpServer.close((error) => (error ? reject(error) : resolve()));
 17	    });
 18	  }
 19	  await server.closeInfrastructure();
 20	}
 21	
 22	function handleSignal(signal: string): void {
 23	  void shutdown(signal).then(
 24	    () => process.exit(0),
 25	    (error: unknown) => {
 26	      console.error('[server] shutdown failed', error);
 27	      process.exit(1);
 28	    },
 29	  );
 30	}
 31	
 32	process.once('SIGINT', () => handleSignal('SIGINT'));
 33	process.once('SIGTERM', () => handleSignal('SIGTERM'));
