  6	import { AuthService } from './auth/authService.js';
  7	import { MemoryAccountRepository, type AccountRepository } from './auth/accountRepository.js';
  8	import { MemoryLoginRateLimit, type LoginRateLimit } from './auth/loginRateLimit.js';
  9	import type { ServerConfig } from './config/config.js';
 10	import { MatchmakingService } from './matchmaking/matchmakingService.js';
 11	import { MemoryMatchmakingStore, type MatchmakingStore } from './matchmaking/matchmakingStore.js';
 12	import { createAuthRouter } from './http/authRoutes.js';
 13	import { createGuestRouter } from './http/guestRoutes.js';
 14	import { createProfileRouter } from './http/profileRoutes.js';
 15	import { createReplayRouter } from './http/replayRoutes.js';
 16	import { MemoryGuestIdentityStore, type GuestIdentityStore } from './identity/guest.js';
 17	import { setupSocket } from './realtime/socket.js';
 18	import { NullReplayRepository, type ReplayRepository } from './db/replayRepository.js';
 19	import { MemoryRatingRepository, type RatingRepository } from './rating/ratingRepository.js';
 20	import { RoomLock, type RoomLockAdapter } from './rooms/lock.js';
 21	import { MemoryRoomMembershipStore, type RoomMembershipStore } from './rooms/membershipStore.js';
 22	import { RoomService } from './rooms/roomService.js';
 23	import { MemoryRoomStore, type RoomStore } from './storage/roomStore.js';
 24	import { BotService } from './bot/botService.js';
 25	
 26	export interface AppDependencies {
 27	  readonly identities?: GuestIdentityStore;
 28	  readonly roomStore?: RoomStore;
 29	  readonly roomLock?: RoomLockAdapter;
 30	  readonly replays?: ReplayRepository;
 31	  readonly memberships?: RoomMembershipStore;
 32	  readonly accounts?: AccountRepository;
 33	  readonly loginRateLimit?: LoginRateLimit;
 34	  readonly ratings?: RatingRepository;
 35	  readonly matchmakingStore?: MatchmakingStore;
 36	  readonly matchmakingLock?: RoomLockAdapter;
 37	  readonly storageName?: 'memory' | 'redis';
 38	}
 39	
 40	export interface PokeWarServer {
 41	  readonly app: express.Express;
 42	  readonly httpServer: HttpServer;
 43	  readonly io: Server;
 44	  readonly rooms: RoomService;
 45	  readonly matchmaking: MatchmakingService;
 46	  readonly bots: BotService;
 47	}
 48	
 49	export function createPokeWarServer(
 50	  config: ServerConfig,
 51	  dependencies: AppDependencies = {},
 52	): PokeWarServer {
 53	  const identities = dependencies.identities ?? new MemoryGuestIdentityStore();
 54	  const accounts = dependencies.accounts ?? new MemoryAccountRepository();
 55	  const auth = new AuthService(accounts, identities);
 56	  const loginRateLimit = dependencies.loginRateLimit ?? new MemoryLoginRateLimit();
 57	  const ratings = dependencies.ratings ?? new MemoryRatingRepository();
 58	  const roomStore = dependencies.roomStore ?? new MemoryRoomStore();
 59	  const replays = dependencies.replays ?? new NullReplayRepository();
 60	  const rooms = new RoomService(roomStore, dependencies.roomLock ?? new RoomLock(), replays);
 61	  const memberships = dependencies.memberships ?? new MemoryRoomMembershipStore();
 62	  const matchmaking = new MatchmakingService(
 63	    dependencies.matchmakingStore ?? new MemoryMatchmakingStore(),
 64	    dependencies.matchmakingLock ?? dependencies.roomLock ?? new RoomLock(),
 65	    rooms,
 66	    memberships,
 67	    ratings,
 68	  );
 69	  const bots = new BotService(rooms);
 70	  const app = express();
 71	  app.disable('x-powered-by');
 72	  app.use(helmet());
 73	  app.use(cors({ origin: [...config.corsOrigins], credentials: true }));
 74	  app.use(express.json({ limit: '16kb' }));
 75	  app.get('/', (_request, response) =>
 76	    response.json({
 77	      service: 'pokewar-server',
 78	      status: 'ok',
 79	      frontend: 'http://localhost:5173/',
 80	      health: '/api/health',
 81	    }),
 82	  );
 83	  app.get('/api/health', (_request, response) =>
 84	    response.json({ ok: true, storage: dependencies.storageName ?? 'memory' }),
 85	  );
 86	  app.use('/api/guest', createGuestRouter(config, identities, auth));
 87	  app.use('/api/auth', createAuthRouter(config, identities, auth, loginRateLimit));
 88	  app.use('/api/profile', createProfileRouter(config, identities, auth, ratings));
 89	  app.use('/api/replays', createReplayRouter(config, identities, replays, auth));
 90	  app.use((_request, response) => response.status(404).json({ code: 'NOT_FOUND' }));
 91	  app.use(
 92	    (
 93	      error: unknown,
 94	      _request: express.Request,
 95	      response: express.Response,
 96	      next: express.NextFunction,
 97	    ) => {
 98	      void next;
 99	      console.error('[http:error]', error);
100	      response.status(500).json({ code: 'INTERNAL_ERROR' });
101	    },
102	  );
103	
104	  const httpServer = createServer(app);
105	  const io = new Server(httpServer, {
106	    cors: { origin: [...config.corsOrigins], credentials: true },
107	    transports: ['websocket'],
108	  });
109	  setupSocket(io, config, identities, rooms, memberships, auth, matchmaking, bots);
110	  return { app, httpServer, io, rooms, matchmaking, bots };
111	}

