  1	import {
  2	  matchmakingAcceptPayloadSchema,
  3	  matchmakingModePayloadSchema,
  4	  roomCommandSchema,
  5	  type MatchmakingState,
  6	} from '@pokewar/protocol';
  7	import { randomBytes } from 'node:crypto';
  8	import type { Server } from 'socket.io';
  9	import { z } from 'zod';
 10	import type { ServerConfig } from '../config/config.js';
 11	import type { AuthService } from '../auth/authService.js';
 12	import { resolveIdentity } from '../auth/resolveIdentity.js';
 13	import type { GuestIdentity, GuestIdentityStore } from '../identity/guest.js';
 14	import type { MatchmakingResult, MatchmakingService } from '../matchmaking/matchmakingService.js';
 15	import type { BotService } from '../bot/botService.js';
 16	import { projectRoom } from '../rooms/projection.js';
 17	import type { RoomService } from '../rooms/roomService.js';
 18	import type { RoomMembershipStore } from '../rooms/membershipStore.js';
 19	import type { RoomState } from '../rooms/model.js';
 20	
 21	const roomIdPayload = z.object({
 22	  roomId: z.string().regex(/^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{5}$/),
 23	});
 24	const createPayload = z.object({ mode: z.enum(['normal', 'quick']).default('normal') });
 25	const readyPayload = roomIdPayload.extend({ ready: z.boolean() });
 26	const modePayload = roomIdPayload.extend({ mode: z.enum(['normal', 'quick']) });
 27	const kickPayload = roomIdPayload.extend({ targetIdentityId: z.string().min(1).max(80) });
 28	const pveLeavePayload = roomIdPayload.extend({ actionId: z.uuid() });
 29	type Ack = (payload: unknown) => void;
 30	type SocketHandler = (payload: unknown, ack: Ack) => Promise<unknown>;
 31	
 32	function reportLifecycleError(error: unknown): void {
 33	  console.error('[socket:lifecycle]', error);
 34	}
 35	
 36	function safeHandler(handler: SocketHandler): (payload: unknown, ack: Ack) => void {
 37	  return (payload, ack) => {
 38	    void handler(payload, ack).catch((error: unknown) => {
 39	      console.error('[socket:handler]', error);
 40	      ack({ ok: false, code: 'INTERNAL_ERROR' });
 41	    });
 42	  };
 43	}
 44	
 45	export function broadcastMatchmaking(
 46	  io: Server,
 47	  updates: ReadonlyMap<string, MatchmakingState>,
 48	): void {
 49	  for (const [identityId, state] of updates) {
 50	    io.to(`identity:${identityId}`).emit('matchmaking:state', state);
 51	  }
 52	}
 53	
 54	export function broadcastRoom(io: Server, room: RoomState): void {
 55	  for (const member of room.members) {
 56	    io.to(`identity:${member.identityId}`).emit(
 57	      'room:snapshot',
 58	      projectRoom(room, member.identityId),
 59	    );
 60	  }
 61	}
 62	
 63	export function setupSocket(
 64	  io: Server,
 65	  config: ServerConfig,
 66	  identities: GuestIdentityStore,
 67	  rooms: RoomService,
 68	  memberships: RoomMembershipStore,
 69	  auth: AuthService,
 70	  matchmaking: MatchmakingService,
 71	  bots: BotService,
 72	): void {
 73	  const controllingSocket = new Map<string, string>();
 74	  const socketIdentities = new Map<string, GuestIdentity>();
 75	
 76	  io.use((socket, next) => {
 77	    void resolveIdentity(
 78	      socket.handshake.headers.cookie,
 79	      config,
 80	      identities,
 81	      auth,
 82	      Date.now(),
 83	    ).then(
 84	      (resolved) => {
 85	        if (!resolved) return next(new Error('IDENTITY_REQUIRED'));
 86	        socketIdentities.set(socket.id, resolved.identity);
 87	        next();
 88	      },
 89	      (error: unknown) =>
 90	        next(error instanceof Error ? error : new Error('IDENTITY_LOOKUP_FAILED')),
 91	    );
 92	  });
 93	
 94	  io.on('connection', (socket) => {
 95	    const identity = socketIdentities.get(socket.id);
 96	    if (!identity) {
 97	      socket.disconnect(true);
 98	      return;
 99	    }
100	    const previous = controllingSocket.get(identity.id);
101	    if (previous && previous !== socket.id) io.to(previous).emit('identity:control-lost');
102	    controllingSocket.set(identity.id, socket.id);
103	
104	    const canControl = () => controllingSocket.get(identity.id) === socket.id;
105	    const rejectReadOnly = (ack: Ack) => {
106	      if (canControl()) return false;
107	      ack({ ok: false, code: 'READ_ONLY_CONNECTION' });
108	      return true;
109	    };
110	    void socket.join(`identity:${identity.id}`);
111	    void matchmaking
112	      .state(identity.id)
113	      .then((state) => socket.emit('matchmaking:state', state))
114	      .catch(reportLifecycleError);
115	    void memberships
116	      .get(identity.id)
117	      .then(async (roomId) => {
118	        if (!roomId) return;
119	        const room = await rooms.get(roomId);
120	        if (!room?.members.some((member) => member.identityId === identity.id)) {
121	          await memberships.delete(identity.id);
122	          return;
123	        }
124	        await socket.join(roomId);
125	        const connected = await rooms.setConnection(roomId, identity.id, true, Date.now());
126	        const current = connected.ok ? connected.value : room;
127	        if (current) {
128	          broadcastRoom(io, current);
129	          socket.emit('room:snapshot', projectRoom(current, identity.id));
130	        }
131	      })
132	      .catch(reportLifecycleError);
133	
134	    const publishMatchmaking = (result: MatchmakingResult) => {
135	      if (!result.ok) return;
136	      broadcastMatchmaking(io, result.updates);
137	      for (const room of result.rooms ?? []) broadcastRoom(io, room);
138	    };
139	    const dissolvePve = async (room: RoomState) => {
140	      if (room.kind !== 'pve') return false;
141	      const dissolved = await rooms.dissolvePve(room.id, identity.id);
142	      if (!dissolved) return false;
143	      await memberships.delete(identity.id);
144	      await socket.leave(room.id);
145	      return true;
146	    };
147	
148	    socket.on(
149	      'matchmaking:enqueue',
150	      safeHandler(async (payload: unknown, ack: Ack) => {
151	        if (rejectReadOnly(ack)) return;
152	        const parsed = matchmakingModePayloadSchema.safeParse(payload);
153	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
154	        const result = await matchmaking.enqueue(
155	          identity,
156	          parsed.data.mode,
157	          parsed.data.targetSize,
158	          parsed.data.allowFallback,
159	          Date.now(),
160	        );
161	        publishMatchmaking(result);
162	        return ack(result.ok ? { ok: true } : result);
163	      }),
164	    );
165	
166	    socket.on(
167	      'pve:start',
168	      safeHandler(async (payload: unknown, ack: Ack) => {
169	        if (rejectReadOnly(ack)) return;
170	        const parsed = z
171	          .object({
172	            mode: z.enum(['normal', 'quick']),
173	            targetSize: z.union([z.literal(4), z.literal(8), z.literal(12)]),
174	          })
175	          .safeParse(payload);
176	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
177	        if (await memberships.get(identity.id))
178	          return ack({ ok: false, code: 'MATCHMAKING_ROOM_CONFLICT' });
179	        const room = await rooms.createPveRoom(
180	          identity,
181	          parsed.data.mode,
182	          parsed.data.targetSize,
183	          Date.now(),
184	        );
185	        await memberships.set(identity.id, room.id);
186	        broadcastRoom(io, room);
187	        void bots.executeBotSequence(room.id, (updated) => {
188	          broadcastRoom(io, updated);
189	          const human = updated.game?.players.find((player) => player.id === identity.id);
190	          if (updated.kind === 'pve' && human?.eliminated) void dissolvePve(updated);
191	        });
192	        return ack({ ok: true });
193	      }),
194	    );
195	
196	    socket.on(
197	      'pve:leave',
198	      safeHandler(async (payload: unknown, ack: Ack) => {
199	        if (rejectReadOnly(ack)) return;
200	        const parsed = pveLeavePayload.safeParse(payload);
201	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
202	        const { roomId, actionId } = parsed.data;
203	        if (config.nodeEnv === 'development') {
204	          console.info('[pve:leave] received', { roomId, actionId, identityId: identity.id });
205	        }
206	        const room = await rooms.get(roomId);
207	        if (!room) {
208	          await memberships.delete(identity.id);
209	          await socket.leave(roomId);
210	          if (config.nodeEnv === 'development') {
211	            console.info('[pve:leave] already-dissolved', { roomId, actionId });
212	          }
213	          return ack({ ok: true, roomId, actionId, leftRoom: true, dissolved: true });
214	        }
215	        if (room.kind !== 'pve') return ack({ ok: false, code: 'INVALID_PHASE' });
216	        if (!room.members.some((member) => member.identityId === identity.id)) {
217	          return ack({ ok: false, code: 'NOT_ROOM_MEMBER' });
218	        }
219	        const dissolved = await rooms.dissolvePve(roomId, identity.id);
220	        await memberships.delete(identity.id);
221	        await socket.leave(roomId);
222	        if (config.nodeEnv === 'development') {
223	          console.info('[pve:leave] cleaned', {
224	            roomId,
225	            actionId,
226	            dissolved,
227	            membershipCleared: true,
228	          });
229	        }
230	        return ack({ ok: true, roomId, actionId, leftRoom: true, dissolved });
231	      }),
232	    );
233	
234	    socket.on(
235	      'matchmaking:cancel',
236	      safeHandler(async (_payload: unknown, ack: Ack) => {
237	        if (rejectReadOnly(ack)) return;
238	        const result = await matchmaking.cancel(identity.id, Date.now());
239	        publishMatchmaking(result);
240	        return ack(result.ok ? { ok: true } : result);
241	      }),
242	    );
243	
244	    socket.on(
245	      'matchmaking:accept',
246	      safeHandler(async (payload: unknown, ack: Ack) => {
247	        if (rejectReadOnly(ack)) return;
248	        const parsed = matchmakingAcceptPayloadSchema.safeParse(payload);
249	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
250	        const result = await matchmaking.accept(identity.id, parsed.data.proposalId, Date.now());
251	        publishMatchmaking(result);
252	        return ack(result.ok ? { ok: true } : result);
253	      }),
254	    );
255	
256	    socket.on(
257	      'matchmaking:decline',
258	      safeHandler(async (_payload: unknown, ack: Ack) => {
259	        if (rejectReadOnly(ack)) return;
260	        const result = await matchmaking.cancel(identity.id, Date.now());
261	        publishMatchmaking(result);
262	        return ack(result.ok ? { ok: true } : result);
263	      }),
264	    );
265	
266	    socket.on(
267	      'matchmaking:get-state',
268	      safeHandler(async (_payload: unknown, ack: Ack) => {
269	        return ack({ ok: true, state: await matchmaking.state(identity.id) });
270	      }),
271	    );
272	
273	    socket.on(
274	      'room:create',
275	      safeHandler(async (payload: unknown, ack: Ack) => {
276	        if (rejectReadOnly(ack)) return;
277	        const parsed = createPayload.safeParse(payload);
278	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
279	        const guarded = await matchmaking.runIfIdle(identity.id, () =>
280	          rooms.create(identity, parsed.data.mode, Date.now()),
281	        );
282	        if (!guarded.ok) return ack({ ok: false, code: 'MATCHMAKING_ALREADY_ACTIVE' });
283	        const room = guarded.value;
284	        await memberships.set(identity.id, room.id);
285	        await socket.join(room.id);
286	        broadcastRoom(io, room);
287	        return ack({ ok: true, room: projectRoom(room, identity.id) });
288	      }),
289	    );
290	
291	    socket.on(
292	      'room:join',
293	      safeHandler(async (payload: unknown, ack: Ack) => {
294	        if (rejectReadOnly(ack)) return;
295	        const parsed = roomIdPayload.safeParse(payload);
296	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
297	        const guarded = await matchmaking.runIfIdle(identity.id, () =>
298	          rooms.join(parsed.data.roomId, identity, Date.now()),
299	        );
300	        if (!guarded.ok) return ack({ ok: false, code: 'MATCHMAKING_ALREADY_ACTIVE' });
301	        const result = guarded.value;
302	        if (!result.ok) return ack(result);
303	        await memberships.set(identity.id, result.value.id);
304	        await socket.join(result.value.id);
305	        broadcastRoom(io, result.value);
306	        return ack({ ok: true, room: projectRoom(result.value, identity.id) });
307	      }),
308	    );
309	
310	    socket.on(
311	      'room:leave',
312	      safeHandler(async (payload: unknown, ack: Ack) => {
313	        if (rejectReadOnly(ack)) return;
314	        const parsed = roomIdPayload.safeParse(payload);
315	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
316	        const result = await rooms.leaveLobby(parsed.data.roomId, identity.id, Date.now());
317	        if (!result.ok) return ack(result);
318	        await memberships.delete(identity.id);
319	        await socket.leave(parsed.data.roomId);
320	        socket.emit('room:left', { roomId: parsed.data.roomId });
321	        if (result.value) broadcastRoom(io, result.value);
322	        return ack({ ok: true });
323	      }),
324	    );
325	
326	    socket.on(
327	      'room:ready',
328	      safeHandler(async (payload: unknown, ack: Ack) => {
329	        if (rejectReadOnly(ack)) return;
330	        const parsed = readyPayload.safeParse(payload);
331	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
332	        const result = await rooms.setReady(
333	          parsed.data.roomId,
334	          identity.id,
335	          parsed.data.ready,
336	          Date.now(),
337	        );
338	        if (!result.ok) return ack(result);
339	        broadcastRoom(io, result.value);
340	        return ack({ ok: true, version: result.value.version });
341	      }),
342	    );
343	
344	    socket.on(
345	      'room:mode',
346	      safeHandler(async (payload: unknown, ack: Ack) => {
347	        if (rejectReadOnly(ack)) return;
348	        const parsed = modePayload.safeParse(payload);
349	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
350	        const result = await rooms.setMode(
351	          parsed.data.roomId,
352	          identity.id,
353	          parsed.data.mode,
354	          Date.now(),
355	        );
356	        if (!result.ok) return ack(result);
357	        broadcastRoom(io, result.value);
358	        return ack({ ok: true, version: result.value.version });
359	      }),
360	    );
361	
362	    socket.on(
363	      'room:kick',
364	      safeHandler(async (payload: unknown, ack: Ack) => {
365	        if (rejectReadOnly(ack)) return;
366	        const parsed = kickPayload.safeParse(payload);
367	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
368	        const result = await rooms.kick(
369	          parsed.data.roomId,
370	          identity.id,
371	          parsed.data.targetIdentityId,
372	          Date.now(),
373	        );
374	        if (!result.ok) return ack(result);
375	        broadcastRoom(io, result.value);
376	        await memberships.delete(parsed.data.targetIdentityId);
377	        io.to(`identity:${parsed.data.targetIdentityId}`).emit('room:kicked', {
378	          roomId: result.value.id,
379	        });
380	        return ack({ ok: true, version: result.value.version });
381	      }),
382	    );
383	
384	    socket.on(
385	      'room:start',
386	      safeHandler(async (payload: unknown, ack: Ack) => {
387	        if (rejectReadOnly(ack)) return;
388	        const parsed = roomIdPayload.safeParse(payload);
389	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
390	        const result = await rooms.start(
391	          parsed.data.roomId,
392	          identity.id,
393	          randomBytes(32).toString('hex'),
394	          Date.now(),
395	        );
396	        if (!result.ok) return ack(result);
397	        broadcastRoom(io, result.value);
398	        return ack({ ok: true, version: result.value.version });
399	      }),
400	    );
401	
402	    socket.on(
403	      'game:return-lobby',
404	      safeHandler(async (payload: unknown, ack: Ack) => {
405	        if (rejectReadOnly(ack)) return;
406	        const parsed = roomIdPayload.safeParse(payload);
407	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
408	        const room = await rooms.get(parsed.data.roomId);
409	        if (!room?.members.some((member) => member.identityId === identity.id)) {
410	          return ack({ ok: false, code: 'NOT_ROOM_MEMBER' });
411	        }
412	        if (room.game?.phase !== 'GAME_OVER') return ack({ ok: false, code: 'INVALID_PHASE' });
413	        await memberships.delete(identity.id);
414	        await socket.leave(parsed.data.roomId);
415	        socket.emit('room:left', { roomId: parsed.data.roomId });
416	        return ack({ ok: true });
417	      }),
418	    );
419	
420	    socket.on(
421	      'game:command',
422	      safeHandler(async (payload: unknown, ack: Ack) => {
423	        if (rejectReadOnly(ack)) return;
424	        const parsed = roomCommandSchema.safeParse(payload);
425	        if (!parsed.success) return ack({ ok: false, code: 'INVALID_PAYLOAD' });
426	        const result = await rooms.command(identity.id, parsed.data, Date.now());
427	        if (!result.ok) return ack(result);
428	        broadcastRoom(io, result.value.room);
429	        const selfPlayer = result.value.room.game?.players.find(
430	          (player) => player.id === identity.id,
431	        );
432	        const shouldDissolve =
433	          result.value.room.kind === 'pve' &&
434	          (selfPlayer?.eliminated === true || parsed.data.kind === 'game:leave-match');
435	        if (shouldDissolve) await dissolvePve(result.value.room);
436	        else
437	          void bots.executeBotSequence(result.value.room.id, (updated) => {
438	            broadcastRoom(io, updated);
439	            const human = updated.game?.players.find((player) => player.id === identity.id);
440	            if (updated.kind === 'pve' && human?.eliminated) void dissolvePve(updated);
441	          });
442	        return ack({
443	          ok: true,
444	          roomVersion: result.value.room.version,
445	          gameVersion: result.value.room.game?.version,
446	          events: result.value.events,
447	        });
448	      }),
449	    );
450	
451	    socket.on('disconnect', () => {
452	      socketIdentities.delete(socket.id);
453	      if (controllingSocket.get(identity.id) !== socket.id) return;
454	      controllingSocket.delete(identity.id);
455	      void memberships
456	        .get(identity.id)
457	        .then(async (roomId) => {
458	          if (!roomId || controllingSocket.has(identity.id)) return;
459	          const room = await rooms.get(roomId);
460	          if (room?.kind === 'pve') {
461	            await rooms.dissolvePve(roomId, identity.id);
462	            await memberships.delete(identity.id);
463	            return;
464	          }
465	          const result = await rooms.setConnection(roomId, identity.id, false, Date.now());
466	          if (result.ok && result.value) broadcastRoom(io, result.value);
467	        })
468	        .catch(reportLifecycleError);
469	    });
470	  });
471	}
  1	import {
  2	  matchmakingStateSchema,
  3	  roomProjectionSchema,
  4	  type GameMode,
  5	  type RoomCommand,
  6	  type MatchSize,
  7	  type MatchmakingState,
  8	  type RoomProjection,
  9	} from '@pokewar/protocol';
 10	import { io, type Socket } from 'socket.io-client';
 11	
 12	export type ConnectionState = 'connecting' | 'connected' | 'disconnected' | 'read-only';
 13	export type GameCommandIntent = RoomCommand extends infer Command
 14	  ? Command extends RoomCommand
 15	    ? Omit<Command, 'actionId'>
 16	    : never
 17	  : never;
 18	export type GameAction = RoomCommand extends infer Command
 19	  ? Command extends RoomCommand
 20	    ? Omit<Command, 'actionId' | 'roomId' | 'expectedVersion'>
 21	    : never
 22	  : never;
 23	
 24	export interface AckResult {
 25	  readonly ok: boolean;
 26	  readonly code?: string;
 27	  readonly room?: unknown;
 28	  readonly roomId?: string;
 29	  readonly actionId?: string;
 30	  readonly leftRoom?: boolean;
 31	  readonly dissolved?: boolean;
 32	}
 33	
 34	export interface RoomSocketHandlers {
 35	  onConnection(state: ConnectionState): void;
 36	  onRoom(room: RoomProjection): void;
 37	  onError(code: string): void;
 38	  onKicked(): void;
 39	  onLeft(): void;
 40	  onMatchmaking(state: MatchmakingState): void;
 41	}
 42	
 43	export interface RoomSocketClient {
 44	  create(mode: GameMode): Promise<AckResult>;
 45	  join(roomId: string): Promise<AckResult>;
 46	  leave(roomId: string): Promise<AckResult>;
 47	  ready(roomId: string, ready: boolean): Promise<AckResult>;
 48	  mode(roomId: string, mode: GameMode): Promise<AckResult>;
 49	  kick(roomId: string, targetIdentityId: string): Promise<AckResult>;
 50	  start(roomId: string): Promise<AckResult>;
 51	  startPve(mode: GameMode, targetSize: 4 | 8 | 12): Promise<AckResult>;
 52	  leavePve(roomId: string): Promise<AckResult>;
 53	  selectStarter(roomId: string, expectedVersion: number, characterId: string): Promise<AckResult>;
 54	  gameCommand(command: GameCommandIntent): Promise<AckResult>;
 55	  returnToLobby(roomId: string): Promise<AckResult>;
 56	  enqueue(mode: GameMode, targetSize: MatchSize, allowFallback: boolean): Promise<AckResult>;
 57	  cancelMatchmaking(): Promise<AckResult>;
 58	  acceptMatch(proposalId: string): Promise<AckResult>;
 59	  declineMatch(): Promise<AckResult>;
 60	  disconnect(): void;
 61	}
 62	
 63	function emit(socket: Socket, event: string, payload: unknown): Promise<AckResult> {
 64	  return new Promise((resolve) => {
 65	    socket.timeout(8_000).emit(event, payload, (error: Error | null, response: AckResult) => {
 66	      resolve(error ? { ok: false, code: 'REQUEST_TIMEOUT' } : response);
 67	    });
 68	  });
 69	}
 70	
 71	export function createRoomSocket(handlers: RoomSocketHandlers): RoomSocketClient {
 72	  const socket = io({ transports: ['websocket'], withCredentials: true, autoConnect: true });
 73	  const acceptRoom = (value: unknown) => {
 74	    const parsed = roomProjectionSchema.safeParse(value);
 75	    if (parsed.success) handlers.onRoom(parsed.data);
 76	    else handlers.onError('INVALID_SERVER_PAYLOAD');
 77	  };
 78	  socket.on('connect', () => handlers.onConnection('connected'));
 79	  socket.on('disconnect', () => handlers.onConnection('disconnected'));
 80	  socket.on('connect_error', () => handlers.onConnection('disconnected'));
 81	  socket.on('identity:control-lost', () => handlers.onConnection('read-only'));
 82	  socket.on('room:snapshot', acceptRoom);
 83	  socket.on('room:kicked', () => handlers.onKicked());
 84	  socket.on('room:left', () => handlers.onLeft());
 85	  socket.on('matchmaking:state', (value: unknown) => {
 86	    const parsed = matchmakingStateSchema.safeParse(value);
 87	    if (parsed.success) handlers.onMatchmaking(parsed.data);
 88	    else handlers.onError('INVALID_SERVER_PAYLOAD');
 89	  });
 90	
 91	  const request = async (event: string, payload: unknown): Promise<AckResult> => {
 92	    const result = await emit(socket, event, payload);
 93	    if (result.room) acceptRoom(result.room);
 94	    if (!result.ok && result.code) handlers.onError(result.code);
 95	    return result;
 96	  };
 97	  return {
 98	    create: (mode) => request('room:create', { mode }),
 99	    join: (roomId) => request('room:join', { roomId }),
100	    leave: (roomId) => request('room:leave', { roomId }),
101	    ready: (roomId, ready) => request('room:ready', { roomId, ready }),
102	    mode: (roomId, mode) => request('room:mode', { roomId, mode }),
103	    kick: (roomId, targetIdentityId) => request('room:kick', { roomId, targetIdentityId }),
104	    start: (roomId) => request('room:start', { roomId }),
105	    startPve: (mode, targetSize) => request('pve:start', { mode, targetSize }),
106	    leavePve: async (roomId) => {
107	      const actionId = crypto.randomUUID();
108	      if (import.meta.env.DEV) console.info('[pve:leave] send', { roomId, actionId });
109	      const result = await request('pve:leave', { roomId, actionId });
110	      if (import.meta.env.DEV) console.info('[pve:leave] ack', { roomId, actionId, result });
111	      return result;
112	    },
113	    selectStarter: (roomId, expectedVersion, characterId) =>
114	      request('game:command', {
115	        roomId,
116	        actionId: crypto.randomUUID(),
117	        expectedVersion,
118	        kind: 'game:select-starter',
119	        characterId,
120	      }),
121	    gameCommand: (command) =>
122	      request('game:command', { ...command, actionId: crypto.randomUUID() }),
123	    returnToLobby: (roomId) => request('game:return-lobby', { roomId }),
124	    enqueue: (mode, targetSize, allowFallback) =>
125	      request('matchmaking:enqueue', { mode, targetSize, allowFallback }),
126	    cancelMatchmaking: () => request('matchmaking:cancel', {}),
127	    acceptMatch: (proposalId) => request('matchmaking:accept', { proposalId }),
128	    declineMatch: () => request('matchmaking:decline', {}),
129	    disconnect: () => socket.disconnect(),
130	  };
131	}
  1	import react from '@vitejs/plugin-react';
  2	import { defineConfig } from 'vitest/config';
  3	
  4	export default defineConfig({
  5	  plugins: [react()],
  6	  server: {
  7	    port: 5173,
  8	    strictPort: true,
  9	    proxy: {
 10	      '/api': 'http://127.0.0.1:3000',
 11	      '/socket.io': { target: 'ws://127.0.0.1:3000', ws: true },
 12	    },
 13	  },
 14	  test: {
 15	    environment: 'jsdom',
 16	    setupFiles: './src/test/setup.ts',
 17	  },
 18	});

