 4	const LOBBY_TTL_SECONDS = 30 * 60;
 5	const FINISHED_TTL_SECONDS = 10 * 60;
 6	const ACTIVE_TTL_SECONDS = 24 * 60 * 60;
 7	
 8	export interface RedisRoomClient {
 9	  get(key: string): Promise<string | null>;
10	  set(key: string, value: string, options?: { EX?: number }): Promise<unknown>;
11	  del(key: string): Promise<number>;
12	}
13	
14	function roomTtl(room: RoomState): number {
15	  if (!room.game) return LOBBY_TTL_SECONDS;
16	  return room.game.phase === 'GAME_OVER' ? FINISHED_TTL_SECONDS : ACTIVE_TTL_SECONDS;
17	}
