19	export class RedisRoomStore implements RoomStore {
20	  constructor(
21	    private readonly client: RedisRoomClient,
22	    private readonly prefix: string,
23	  ) {}
24	
25	  async get(roomId: string): Promise<RoomState | null> {
26	    const value = await this.client.get(this.key(roomId));
27	    if (!value) return null;
28	    return JSON.parse(value) as RoomState;
29	  }
30	
31	  async save(room: RoomState): Promise<void> {
32	    await this.client.set(this.key(room.id), JSON.stringify(room), { EX: roomTtl(room) });
33	  }
34	
35	  async delete(roomId: string): Promise<void> {
36	    await this.client.del(this.key(roomId));
37	  }
38	
39	  private key(roomId: string): string {
40	    return `${this.prefix}room:${roomId}`;
41	  }
42	}
 1	import type { RoomState } from '../rooms/model.js';
 2	import { deadlineScore, extractDeadlines } from '../scheduler/deadline.js';
 3	import type { RoomStore } from './roomStore.js';
 4	
 5	const LOBBY_TTL_SECONDS = 30 * 60;
 6	const FINISHED_TTL_SECONDS = 10 * 60;
 7	const ACTIVE_TTL_SECONDS = 24 * 60 * 60;
 8	
 9	const SAVE_SCRIPT = `
10	local old = redis.call('SMEMBERS', KEYS[3])
11	if #old > 0 then redis.call('ZREM', KEYS[2], unpack(old)) end
12	redis.call('DEL', KEYS[3])
13	redis.call('SET', KEYS[1], ARGV[1], 'EX', ARGV[2])
14	for index = 3, #ARGV, 2 do
15	  redis.call('ZADD', KEYS[2], ARGV[index], ARGV[index + 1])
16	  redis.call('SADD', KEYS[3], ARGV[index + 1])
17	end
18	return 1
19	`;
20	
21	const DELETE_SCRIPT = `
22	local old = redis.call('SMEMBERS', KEYS[3])
23	if #old > 0 then redis.call('ZREM', KEYS[2], unpack(old)) end
24	redis.call('DEL', KEYS[3])
25	return redis.call('DEL', KEYS[1])
26	`;
27	
28	export interface RedisIndexedRoomClient {
29	  get(key: string): Promise<string | null>;
30	  eval(script: string, options: { keys: string[]; arguments: string[] }): Promise<unknown>;
31	}
32	
33	function roomTtl(room: RoomState): number {
34	  if (!room.game) return LOBBY_TTL_SECONDS;
35	  return room.game.phase === 'GAME_OVER' ? FINISHED_TTL_SECONDS : ACTIVE_TTL_SECONDS;
36	}
37	
38	export class RedisIndexedRoomStore implements RoomStore {
39	  constructor(
40	    private readonly client: RedisIndexedRoomClient,
41	    private readonly prefix: string,
42	  ) {}
43	
44	  async get(roomId: string): Promise<RoomState | null> {
45	    const value = await this.client.get(this.roomKey(roomId));
46	    return value ? (JSON.parse(value) as RoomState) : null;
47	  }
48	
49	  async save(room: RoomState): Promise<void> {
50	    const taskArguments = extractDeadlines(room).flatMap((task) => [
51	      String(deadlineScore(task)),
52	      JSON.stringify(task),
53	    ]);
54	    await this.client.eval(SAVE_SCRIPT, {
55	      keys: [this.roomKey(room.id), this.deadlineKey(), this.roomDeadlineKey(room.id)],
56	      arguments: [JSON.stringify(room), String(roomTtl(room)), ...taskArguments],
57	    });
58	  }
59	
60	  async delete(roomId: string): Promise<void> {
61	    await this.client.eval(DELETE_SCRIPT, {
62	      keys: [this.roomKey(roomId), this.deadlineKey(), this.roomDeadlineKey(roomId)],
63	      arguments: [],
64	    });
65	  }
66	
67	  private roomKey(roomId: string): string {
68	    return `${this.prefix}room:${roomId}`;
69	  }
70	
71	  private deadlineKey(): string {
72	    return `${this.prefix}deadlines`;
73	  }
74	
75	  private roomDeadlineKey(roomId: string): string {
76	    return `${this.prefix}deadline-room:${roomId}`;
77	  }
78	}

