 1	import { loginAccountSchema, registerAccountSchema } from '@pokewar/protocol';
 2	import { Router } from 'express';
 3	import type { ServerConfig } from '../config/config.js';
 4	import type { GuestIdentityStore } from '../identity/guest.js';
 5	import type { AuthService } from '../auth/authService.js';
 6	import type { LoginRateLimit } from '../auth/loginRateLimit.js';
 7	import { resolveIdentity } from '../auth/resolveIdentity.js';
 8	import { serializeAccountCookie } from '../auth/session.js';
 9	import { asyncHandler } from './asyncHandler.js';
10	
11	function publicIdentity(identity: {
12	  readonly displayName: string;
13	  readonly kind: 'guest' | 'account' | 'bot';
14	}) {
15	  return {
16	    displayName: identity.displayName,
17	    kind: identity.kind === 'bot' ? 'guest' : identity.kind,
18	  };
19	}
20	
21	export function createAuthRouter(
22	  config: ServerConfig,
23	  identities: GuestIdentityStore,
24	  auth: AuthService,
25	  limiter: LoginRateLimit,
26	): Router {
27	  const router = Router();
28	  router.post(
29	    '/register',
30	    asyncHandler(async (request, response) => {
31	      const parsed = registerAccountSchema.safeParse(request.body);
32	      if (!parsed.success) return response.status(400).json({ code: 'INVALID_PAYLOAD' });
33	      const resolved = await resolveIdentity(
34	        request.headers.cookie,
35	        config,
36	        identities,
37	        auth,
38	        Date.now(),
39	      );
40	      if (resolved?.identity.kind !== 'guest')
41	        return response.status(401).json({ code: 'GUEST_IDENTITY_REQUIRED' });
42	      const result = await auth.register(resolved.identity, parsed.data, Date.now());
43	      if (!result.ok) return response.status(409).json({ code: result.code });
44	      response.setHeader(
45	        'Set-Cookie',
46	        serializeAccountCookie(result.token, config.nodeEnv === 'production'),
47	      );
48	      return response.status(201).json({ identity: publicIdentity(result.identity) });
49	    }),
50	  );
51	
52	  router.post(
53	    '/login',
54	    asyncHandler(async (request, response) => {
55	      const parsed = loginAccountSchema.safeParse(request.body);
56	      if (!parsed.success) return response.status(400).json({ code: 'INVALID_PAYLOAD' });
57	      const clientAddress = request.ip ?? request.socket.remoteAddress ?? 'unknown';
58	      const key = `${clientAddress}:${parsed.data.loginName}`;
59	      if (await limiter.isBlocked(key, Date.now()))
60	        return response.status(429).json({ code: 'LOGIN_RATE_LIMITED' });
61	      const result = await auth.login(parsed.data, Date.now());
62	      if (!result.ok) {
63	        await limiter.recordFailure(key, Date.now());
64	        return response.status(401).json({ code: 'INVALID_CREDENTIALS' });
65	      }
66	      await limiter.clear(key);
67	      response.setHeader(
68	        'Set-Cookie',
69	        serializeAccountCookie(result.token, config.nodeEnv === 'production'),
70	      );
71	      return response.json({ identity: publicIdentity(result.identity) });
72	    }),
73	  );
74	
75	  router.post(
76	    '/logout',
77	    asyncHandler(async (request, response) => {
78	      const resolved = await resolveIdentity(
79	        request.headers.cookie,
80	        config,
81	        identities,
82	        auth,
83	        Date.now(),
84	      );
85	      if (resolved?.accountToken) await auth.revoke(resolved.accountToken);
86	      response.setHeader(
87	        'Set-Cookie',
88	        serializeAccountCookie('', config.nodeEnv === 'production', 0),
89	      );
90	      return response.status(204).end();
91	    }),
92	  );
93	  return router;
94	}

