  1	import { randomUUID } from 'node:crypto';
  2	import type { RoomLockAdapter } from './lock.js';
  3	
  4	const RELEASE_SCRIPT = `
  5	if redis.call('GET', KEYS[1]) == ARGV[1] then
  6	  return redis.call('DEL', KEYS[1])
  7	end
  8	return 0
  9	`;
 10	
 11	export interface RedisLockClient {
 12	  set(key: string, value: string, options: { NX: true; PX: number }): Promise<string | null>;
 13	  eval(script: string, options: { keys: string[]; arguments: string[] }): Promise<unknown>;
 14	}
 15	
 16	export interface RedisLockOptions {
 17	  readonly leaseMs?: number;
 18	  readonly waitMs?: number;
 19	  readonly retryMs?: number;
 20	}
 21	
 22	export class RedisRoomLock implements RoomLockAdapter {
 23	  readonly #leaseMs: number;
 24	  readonly #waitMs: number;
 25	  readonly #retryMs: number;
 26	
 27	  constructor(
 28	    private readonly client: RedisLockClient,
 29	    private readonly prefix: string,
 30	    options: RedisLockOptions = {},
 31	  ) {
 32	    this.#leaseMs = options.leaseMs ?? 10_000;
 33	    this.#waitMs = options.waitMs ?? 2_000;
 34	    this.#retryMs = options.retryMs ?? 25;
 35	  }
 36	
 37	  async run<T>(roomId: string, task: () => Promise<T>): Promise<T> {
 38	    const key = `${this.prefix}lock:room:${roomId}`;
 39	    const token = randomUUID();
 40	    const deadline = Date.now() + this.#waitMs;
 41	    let result = await this.client.set(key, token, { NX: true, PX: this.#leaseMs });
 42	    while (result !== 'OK') {
 43	      if (Date.now() >= deadline) throw new Error('ROOM_LOCK_TIMEOUT');
 44	      await new Promise((resolve) => setTimeout(resolve, this.#retryMs));
 45	      result = await this.client.set(key, token, { NX: true, PX: this.#leaseMs });
 46	    }
 47	    try {
 48	      return await task();
 49	    } finally {
 50	      await this.client.eval(RELEASE_SCRIPT, { keys: [key], arguments: [token] });
 51	    }
 52	  }
 53	}
  1	import {
  2	  createGame,
  3	  decide,
  4	  type DomainEvent,
  5	  type GameCommand,
  6	  type GameMode,
  7	  type TransitionResult,
  8	} from '@pokewar/domain';
  9	import type { RoomCommand } from '@pokewar/protocol';
 10	import { randomBytes, randomUUID } from 'node:crypto';
 11	import type { ReplayRepository } from '../db/replayRepository.js';
 12	import { deadlineCommand, gameForDeadline, type DeadlineTask } from '../scheduler/deadline.js';
 13	import { NullReplayRepository } from '../db/replayRepository.js';
 14	import { createBotIdentity, type GuestIdentity } from '../identity/guest.js';
 15	import type { RoomMutation, RoomState } from './model.js';
 16	import type { RoomLockAdapter } from './lock.js';
 17	import type { RoomStore } from '../storage/roomStore.js';
 18	
 19	const ROOM_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
 20	const MAX_PLAYERS = 12;
 21	const KICK_BAN_MS = 30_000;
 22	
 23	export class RoomService {
 24	  constructor(
 25	    private readonly store: RoomStore,
 26	    private readonly lock: RoomLockAdapter,
 27	    private readonly replays: ReplayRepository = new NullReplayRepository(),
 28	  ) {}
 29	
 30	  async allocateRoomId(): Promise<string> {
 31	    return this.createRoomId();
 32	  }
 33	
 34	  async create(identity: GuestIdentity, mode: GameMode, now: number): Promise<RoomState> {
 35	    const id = await this.createRoomId();
 36	    const room: RoomState = {
 37	      id,
 38	      version: 0,
 39	      hostIdentityId: identity.id,
 40	      kind: 'private',
 41	      mode,
 42	      members: [
 43	        {
 44	          identityId: identity.id,
 45	          displayName: identity.displayName,
 46	          ready: true,
 47	          connected: true,
 48	          joinedAt: now,
 49	        },
 50	      ],
 51	      bannedUntil: {},
 52	      game: null,
 53	      createdAt: now,
 54	      updatedAt: now,
 55	    };
 56	    await this.store.save(room);
 57	    return room;
 58	  }
 59	
 60	  async createMatchmade(
 61	    roomId: string,
 62	    players: readonly GuestIdentity[],
 63	    mode: GameMode,
 64	    seed: string,
 65	    now: number,
 66	    kind: 'matchmade' | 'pve' = 'matchmade',
 67	  ): Promise<RoomState> {
 68	    if (![4, 8, 12].includes(players.length)) throw new Error('INVALID_MATCHMADE_PLAYER_COUNT');
 69	    if (new Set(players.map((player) => player.id)).size !== players.length) {
 70	      throw new Error('DUPLICATE_MATCHMADE_PLAYER');
 71	    }
 72	    return this.lock.run(roomId, async () => {
 73	      const existing = await this.store.get(roomId);
 74	      if (existing) {
 75	        const expectedIds = players.map((player) => player.id).sort();
 76	        const existingIds = existing.members.map((member) => member.identityId).sort();
 77	        if (
 78	          existing.kind === kind &&
 79	          existing.mode === mode &&
 80	          existingIds.join('|') === expectedIds.join('|') &&
 81	          existing.game
 82	        ) {
 83	          return existing;
 84	        }
 85	        throw new Error('MATCHMADE_ROOM_ID_COLLISION');
 86	      }
 87	      const members = players.map((player) => ({
 88	        identityId: player.id,
 89	        displayName: player.displayName,
 90	        ready: true,
 91	        connected: true,
 92	        joinedAt: now,
 93	      }));
 94	      const game = createGame({
 95	        id: roomId,
 96	        mode,
 97	        players: players.map((player) => ({ id: player.id, displayName: player.displayName })),
 98	        seed,
 99	        now,
100	      });
101	      const firstPlayer = players[0];
102	      if (!firstPlayer) throw new Error('MATCHMADE_HOST_REQUIRED');
103	      const room: RoomState = {
104	        id: roomId,
105	        version: 1,
106	        hostIdentityId: firstPlayer.id,
107	        kind,
108	        mode,
109	        members,
110	        bannedUntil: {},
111	        game,
112	        createdAt: now,
113	        updatedAt: now,
114	      };
115	      await this.store.save(room);
116	      return room;
117	    });
118	  }
119	
120	  async createPveRoom(
121	    human: GuestIdentity,
122	    mode: GameMode,
123	    targetSize: 4 | 8 | 12,
124	    now: number,
125	  ): Promise<RoomState> {
126	    const roomId = await this.createRoomId();
127	    const bots: GuestIdentity[] = [];
128	    for (let i = 0; i < targetSize - 1; i += 1) {
129	      bots.push(createBotIdentity(`bot:${roomId}:${String(i)}`));
130	    }
131	    return this.createMatchmade(
132	      roomId,
133	      [human, ...bots],
134	      mode,
135	      randomBytes(32).toString('hex'),
136	      now,
137	      'pve',
138	    );
139	  }
140	
141	  async get(roomId: string): Promise<RoomState | null> {
142	    return this.store.get(roomId);
143	  }
144	
145	  async dissolvePve(roomId: string, humanId: string): Promise<boolean> {
146	    return this.lock.run(roomId, async () => {
147	      const room = await this.store.get(roomId);
148	      if (room?.kind !== 'pve') return false;
149	      const human = room.members.find((member) => member.identityId === humanId);
150	      if (!human || human.identityId.startsWith('bot:')) return false;
151	      await this.store.delete(roomId);
152	      return true;
153	    });
154	  }
155	
156	  async executeBotCommand(roomId: string, command: GameCommand): Promise<RoomState | null> {
157	    return this.lock.run(roomId, async () => {
158	      const room = await this.store.get(roomId);
159	      if (!room?.game) return null;
160	      const result = decide(room.game, command);
161	      if (!result.ok) return null;
162	      return this.saveTransition(room, result, command.now);
163	    });
164	  }
165	
166	  async join(roomId: string, identity: GuestIdentity, now: number): Promise<RoomMutation> {
167	    return this.lock.run(roomId, async () => {
168	      const room = await this.store.get(roomId);
169	      if (!room) return { ok: false, code: 'ROOM_NOT_FOUND' };
170	      if (room.game || room.kind === 'matchmade') {
171	        return { ok: false, code: 'ROOM_ALREADY_STARTED' };
172	      }
173	      if ((room.bannedUntil[identity.id] ?? 0) > now) return { ok: false, code: 'PLAYER_BANNED' };
174	      if (room.members.some((member) => member.identityId === identity.id)) {
175	        return { ok: false, code: 'ALREADY_IN_ROOM' };
176	      }
177	      if (room.members.length >= MAX_PLAYERS) return { ok: false, code: 'ROOM_FULL' };
178	      const updated: RoomState = {
179	        ...room,
180	        version: room.version + 1,
181	        members: [
182	          ...room.members,
183	          {
184	            identityId: identity.id,
185	            displayName: identity.displayName,
186	            ready: false,
187	            connected: true,
188	            joinedAt: now,
189	          },
190	        ],
191	        updatedAt: now,
192	      };
193	      await this.store.save(updated);
194	      return { ok: true, value: updated };
195	    });
196	  }
197	
198	  async leaveLobby(
199	    roomId: string,
200	    identityId: string,
201	    now: number,
202	  ): Promise<RoomMutation<RoomState | null>> {
203	    return this.lock.run(roomId, async () => {
204	      const room = await this.store.get(roomId);
205	      if (!room) return { ok: false, code: 'ROOM_NOT_FOUND' };
206	      if (room.game || room.kind === 'matchmade') return { ok: false, code: 'INVALID_PHASE' };
207	      if (!room.members.some((member) => member.identityId === identityId)) {
208	        return { ok: false, code: 'NOT_ROOM_MEMBER' };
209	      }
210	      const members = room.members.filter((member) => member.identityId !== identityId);
211	      if (members.length === 0) {
212	        await this.store.delete(roomId);
213	        return { ok: true, value: null };
214	      }
215	      const nextHost =
