452	  private async updateLobby(
453	    roomId: string,
454	    identityId: string,
455	    now: number,
456	    update: (room: RoomState) => RoomState | null,
457	    nullCode: 'NOT_ROOM_HOST' | 'NOT_ROOM_MEMBER' = 'NOT_ROOM_MEMBER',
458	  ): Promise<RoomMutation> {
459	    return this.lock.run(roomId, async () => {
460	      const room = await this.store.get(roomId);
461	      if (!room) return { ok: false, code: 'ROOM_NOT_FOUND' };
462	      if (room.game) return { ok: false, code: 'ROOM_ALREADY_STARTED' };
463	      if (!room.members.some((member) => member.identityId === identityId)) {
464	        return { ok: false, code: 'NOT_ROOM_MEMBER' };
465	      }
466	      const changed = update(room);
467	      if (!changed) return { ok: false, code: nullCode };
468	      const updated = { ...changed, version: room.version + 1, updatedAt: now };
469	      await this.store.save(updated);
470	      return { ok: true, value: updated };
471	    });
472	  }
