 11	export interface RedisLockClient {
 12	  set(key: string, value: string, options: { NX: true; PX: number }): Promise<string | null>;
 13	  eval(script: string, options: { keys: string[]; arguments: string[] }): Promise<unknown>;
 14	}
 15	
 16	export interface RedisLockOptions {
 17	  readonly leaseMs?: number;
 18	  readonly waitMs?: number;
 19	  readonly retryMs?: number;
 20	}
 21	
 22	export class RedisRoomLock implements RoomLockAdapter {
 23	  readonly #leaseMs: number;
 24	  readonly #waitMs: number;
 25	  readonly #retryMs: number;
 26	
 27	  constructor(
 28	    private readonly client: RedisLockClient,
 29	    private readonly prefix: string,
 30	    options: RedisLockOptions = {},
 31	  ) {
 32	    this.#leaseMs = options.leaseMs ?? 10_000;
 33	    this.#waitMs = options.waitMs ?? 2_000;
 34	    this.#retryMs = options.retryMs ?? 25;
 35	  }
 36	
 37	  async run<T>(roomId: string, task: () => Promise<T>): Promise<T> {
 38	    const key = `${this.prefix}lock:room:${roomId}`;
 39	    const token = randomUUID();
 40	    const deadline = Date.now() + this.#waitMs;
 41	    let result = await this.client.set(key, token, { NX: true, PX: this.#leaseMs });
 42	    while (result !== 'OK') {
 43	      if (Date.now() >= deadline) throw new Error('ROOM_LOCK_TIMEOUT');
 44	      await new Promise((resolve) => setTimeout(resolve, this.#retryMs));
 45	      result = await this.client.set(key, token, { NX: true, PX: this.#leaseMs });
 46	    }
 47	    try {
 48	      return await task();
 49	    } finally {
 50	      await this.client.eval(RELEASE_SCRIPT, { keys: [key], arguments: [token] });
 51	    }
 52	  }
 53	}
