260	      now,
261	      (room) => {
262	        if (room.hostIdentityId !== identityId) return null;
263	        return {
264	          ...room,
265	          mode,
266	          members: room.members.map((member) =>
267	            member.identityId === room.hostIdentityId ? member : { ...member, ready: false },
268	          ),
269	        };
270	      },
271	      'NOT_ROOM_HOST',
272	    );
273	  }
274	
275	  async kick(roomId: string, hostId: string, targetId: string, now: number): Promise<RoomMutation> {
276	    return this.updateLobby(
277	      roomId,
278	      hostId,
279	      now,
280	      (room) => {
281	        if (room.hostIdentityId !== hostId) return null;
282	        if (targetId === hostId || !room.members.some((member) => member.identityId === targetId))
283	          return null;
284	        return {
285	          ...room,
286	          members: room.members.filter((member) => member.identityId !== targetId),
287	          bannedUntil: { ...room.bannedUntil, [targetId]: now + KICK_BAN_MS },
288	        };
289	      },
290	      'NOT_ROOM_HOST',
291	    );
292	  }
293	
294	  async start(roomId: string, hostId: string, seed: string, now: number): Promise<RoomMutation> {
295	    return this.lock.run(roomId, async () => {
296	      const room = await this.store.get(roomId);
297	      if (!room) return { ok: false, code: 'ROOM_NOT_FOUND' };
298	      if (room.hostIdentityId !== hostId) return { ok: false, code: 'NOT_ROOM_HOST' };
299	      if (room.kind === 'matchmade') return { ok: false, code: 'INVALID_PHASE' };
300	      if (room.game) return { ok: false, code: 'ROOM_ALREADY_STARTED' };
301	      if (room.members.length < 2) return { ok: false, code: 'INVALID_PLAYER_COUNT' };
302	      if (!room.members.every((member) => member.identityId === hostId || member.ready)) {
303	        return { ok: false, code: 'NOT_ALL_READY' };
304	      }
305	      const game = createGame({
306	        id: room.id,
307	        mode: room.mode,
308	        players: room.members.map((member) => ({
309	          id: member.identityId,
310	          displayName: member.displayName,
311	        })),
312	        seed,
313	        now,
314	      });
315	      const updated: RoomState = {
316	        ...room,
317	        version: room.version + 1,
318	        game,
319	        updatedAt: now,
320	      };
321	      await this.store.save(updated);
322	      return { ok: true, value: updated };
323	    });
324	  }
325	
326	  async command(
327	    identityId: string,
328	    command: RoomCommand,
329	    now: number,
330	  ): Promise<RoomMutation<{ room: RoomState; events: readonly DomainEvent[] }>> {
331	    return this.lock.run(command.roomId, async () => {
332	      const room = await this.store.get(command.roomId);
333	      if (!room) return { ok: false, code: 'ROOM_NOT_FOUND' };
334	      if (!room.members.some((member) => member.identityId === identityId)) {
335	        return { ok: false, code: 'NOT_ROOM_MEMBER' };
336	      }
337	      if (!room.game) return { ok: false, code: 'INVALID_PHASE' };
338	      const domainCommand = this.toDomainCommand(command, identityId, now);
339	      const result = decide(room.game, domainCommand);
340	      if (!result.ok) return { ok: false, code: result.code };
341	      const updated = await this.saveTransition(room, result, now);
342	      return { ok: true, value: { room: updated, events: result.events } };
343	    });
344	  }
345	
346	  async setConnection(
347	    roomId: string,
348	    identityId: string,
349	    connected: boolean,
350	    now: number,
351	  ): Promise<RoomMutation<RoomState | null>> {
352	    return this.lock.run(roomId, async () => {
353	      const room = await this.store.get(roomId);
354	      if (!room) return { ok: true, value: null };
355	      const member = room.members.find((candidate) => candidate.identityId === identityId);
356	      if (!member) return { ok: true, value: null };
357	      if (
358	        member.connected === connected &&
359	        (!room.game ||
360	          room.game.players.find((player) => player.id === identityId)?.connected === connected)
361	      ) {
362	        return { ok: true, value: room };
363	      }
364	      if (!room.game) {
365	        const updated: RoomState = {
366	          ...room,
367	          version: room.version + 1,
368	          members: room.members.map((candidate) =>
369	            candidate.identityId === identityId ? { ...candidate, connected } : candidate,
370	          ),
371	          updatedAt: now,
372	        };
373	        await this.store.save(updated);
374	        return { ok: true, value: updated };
375	      }
376	      const command: GameCommand = {
377	        actionId: `connection:${identityId}:${connected ? 'online' : 'offline'}:${String(room.game.version)}`,
378	        expectedVersion: room.game.version,
379	        playerId: identityId,
380	        now,
381	        kind: connected ? 'system:player-reconnected' : 'system:player-disconnected',
382	      };
383	      const result = decide(room.game, command);
384	      if (!result.ok) return { ok: true, value: room };
385	      const updated = await this.saveTransition(room, result, now, {
386	        identityId,
387	        connected,
388	      });
389	      return { ok: true, value: updated };
390	    });
391	  }
392	
393	  async processDeadline(task: DeadlineTask, now: number): Promise<RoomMutation<RoomState | null>> {
394	    return this.lock.run(task.roomId, async () => {
395	      const room = await this.store.get(task.roomId);
396	      if (!room) return { ok: true, value: null };
397	      const game = gameForDeadline(room, task);
398	      if (!game) return { ok: true, value: null };
399	      const result = decide(game, deadlineCommand(task, now));
400	      if (!result.ok) return { ok: true, value: null };
401	      const updated = await this.saveTransition(room, result, now);
402	      return { ok: true, value: updated };
403	    });
404	  }
405	
406	  private async saveTransition(
407	    room: RoomState,
408	    result: Extract<TransitionResult, { readonly ok: true }>,
409	    now: number,
410	    memberConnection?: { readonly identityId: string; readonly connected: boolean },
411	  ): Promise<RoomState> {
412	    if (!room.game) throw new Error('GAME_REQUIRED_FOR_TRANSITION');
413	    const updated: RoomState = {
414	      ...room,
415	      version: room.version + 1,
416	      game: result.state,
417	      eventHistory: [
418	        ...(room.eventHistory ?? []),
419	        { gameVersion: result.state.version, events: result.events },
420	      ].slice(-10),
421	      members: memberConnection
422	        ? room.members.map((member) =>
423	            member.identityId === memberConnection.identityId
424	              ? { ...member, connected: memberConnection.connected }
425	              : member,
426	          )
427	        : room.members,
428	      updatedAt: now,
429	    };
430	    if (room.game.phase !== 'GAME_OVER' && result.state.phase === 'GAME_OVER') {
431	      const gameOver = result.events.find((event) => event.kind === 'game:over');
432	      if (!gameOver) throw new Error('GAME_OVER_EVENT_REQUIRED');
433	      await this.replays.save({
434	        roomId: room.id,
435	        finishedAt: now,
436	        winnerPlayerId: gameOver.winnerPlayerId,
437	        participantIds: room.members.map((member) => member.identityId),
438	        summary: {
439	          mode: room.mode,
440	          playerCount: room.members.length,
441	          winnerDisplayName:
442	            room.members.find((member) => member.identityId === gameOver.winnerPlayerId)
443	              ?.displayName ?? 'unknown',
444	        },
445	        game: result.state,
446	      });
447	    }
448	    await this.store.save(updated);
449	    return updated;
450	  }
451	
452	  private async updateLobby(
453	    roomId: string,
454	    identityId: string,
455	    now: number,
456	    update: (room: RoomState) => RoomState | null,
457	    nullCode: 'NOT_ROOM_HOST' | 'NOT_ROOM_MEMBER' = 'NOT_ROOM_MEMBER',
458	  ): Promise<RoomMutation> {
459	    return this.lock.run(roomId, async () => {
460	      const room = await this.store.get(roomId);
461	      if (!room) return { ok: false, code: 'ROOM_NOT_FOUND' };
462	      if (room.game) return { ok: false, code: 'ROOM_ALREADY_STARTED' };
463	      if (!room.members.some((member) => member.identityId === identityId)) {
464	        return { ok: false, code: 'NOT_ROOM_MEMBER' };
465	      }
466	      const changed = update(room);
467	      if (!changed) return { ok: false, code: nullCode };
468	      const updated = { ...changed, version: room.version + 1, updatedAt: now };
469	      await this.store.save(updated);
470	      return { ok: true, value: updated };
471	    });
472	  }
473	
474	  private toDomainCommand(command: RoomCommand, playerId: string, now: number): GameCommand {
475	    const base = {
476	      actionId: command.actionId,
477	      expectedVersion: command.expectedVersion,
478	      playerId,
479	      now,
480	    };
481	    switch (command.kind) {
482	      case 'game:select-starter':
483	        return { ...base, kind: command.kind, characterId: command.characterId };
484	      case 'game:create-fusion':
485	        return {
486	          ...base,
487	          kind: command.kind,
488	          cardIds: command.cardIds,
489	          selectedSuit: command.selectedSuit,
490	          fusedCardId: randomUUID(),
491	        };
492	      case 'game:play-cards':
493	        return {
494	          ...base,
495	          kind: command.kind,
496	          cardIds: command.cardIds,
497	          ...(command.targetPlayerId ? { targetPlayerId: command.targetPlayerId } : {}),
498	        };
499	      case 'game:rescue-with-joker':
500	        return { ...base, kind: command.kind, jokerCardId: command.jokerCardId };
501	      case 'game:decline-rescue':
502	      case 'game:leave-match':
503	        return { ...base, kind: command.kind };
504	      case 'game:select-replacement':
505	        return { ...base, kind: command.kind, characterId: command.characterId };
506	      case 'game:execute-character':
507	        return {
508	          ...base,
509	          kind: command.kind,
510	          jokerCardIds: command.jokerCardIds,
511	          targetPlayerId: command.targetPlayerId,
512	        };
513	    }
514	  }
515	
516	  private async createRoomId(): Promise<string> {
517	    for (let attempt = 0; attempt < 100; attempt += 1) {
518	      const bytes = randomBytes(5);
519	      const id = Array.from(bytes, (byte) => ROOM_CHARS[byte % ROOM_CHARS.length]).join('');
520	      if (!(await this.store.get(id))) return id;
521	    }
522	    throw new Error('ROOM_ID_EXHAUSTED');
523	  }
524	}

