  1	import type { Pool, PoolClient } from 'pg';
  2	import type {
  3	  AccountRecord,
  4	  AccountRepository,
  5	  NewAccountSession,
  6	  RegisterAccountResult,
  7	} from './accountRepository.js';
  8	
  9	interface AccountRow {
 10	  readonly identity_id: string;
 11	  readonly login_name: string;
 12	  readonly password_hash: string;
 13	  readonly nickname: string;
 14	  readonly display_name: string;
 15	  readonly created_at: Date;
 16	}
 17	
 18	function account(row: AccountRow): AccountRecord {
 19	  return {
 20	    identityId: row.identity_id,
 21	    loginName: row.login_name,
 22	    passwordHash: row.password_hash,
 23	    nickname: row.nickname,
 24	    displayName: row.display_name,
 25	    createdAt: row.created_at.getTime(),
 26	  };
 27	}
 28	
 29	async function insertSession(
 30	  client: Pool | PoolClient,
 31	  identityId: string,
 32	  session: NewAccountSession,
 33	): Promise<void> {
 34	  await client.query(
 35	    `INSERT INTO account_sessions (token_hash, identity_id, expires_at, created_at, last_used_at)
 36	     VALUES ($1, $2, $3, $4, $4)`,
 37	    [session.tokenHash, identityId, new Date(session.expiresAt), new Date(session.createdAt)],
 38	  );
 39	}
 40	
 41	export class PostgresAccountRepository implements AccountRepository {
 42	  constructor(private readonly pool: Pool) {}
 43	
 44	  async register(
 45	    record: AccountRecord,
 46	    session: NewAccountSession,
 47	  ): Promise<RegisterAccountResult> {
 48	    const client = await this.pool.connect();
 49	    try {
 50	      await client.query('BEGIN');
 51	      const inserted = await client.query(
 52	        `INSERT INTO accounts (identity_id, login_name, password_hash, nickname, display_name, created_at)
 53	         VALUES ($1, $2, $3, $4, $5, $6)
 54	         ON CONFLICT DO NOTHING RETURNING identity_id`,
 55	        [
 56	          record.identityId,
 57	          record.loginName,
 58	          record.passwordHash,
 59	          record.nickname,
 60	          record.displayName,
 61	          new Date(record.createdAt),
 62	        ],
 63	      );
 64	      if (inserted.rowCount !== 1) {
 65	        const existing = await client.query<{ identity_id: string; login_name: string }>(
 66	          `SELECT identity_id, login_name FROM accounts WHERE identity_id = $1 OR login_name = $2`,
 67	          [record.identityId, record.loginName],
 68	        );
 69	        await client.query('ROLLBACK');
 70	        return existing.rows.some((row) => row.identity_id === record.identityId)
 71	          ? 'identity-registered'
 72	          : 'login-taken';
 73	      }
 74	      for (const mode of ['normal', 'quick'] as const) {
 75	        await client.query(
 76	          `INSERT INTO account_ratings (identity_id, mode, rating, deviation, volatility, ranked_games, wins, losses)
 77	           VALUES ($1, $2, 1500, 350, 0.06, 0, 0, 0)`,
 78	          [record.identityId, mode],
 79	        );
 80	      }
 81	      await insertSession(client, record.identityId, session);
 82	      await client.query('COMMIT');
 83	      return 'created';
 84	    } catch (error) {
 85	      await client.query('ROLLBACK');
 86	      throw error;
 87	    } finally {
 88	      client.release();
 89	    }
 90	  }
 91	
 92	  async findByLoginName(loginName: string): Promise<AccountRecord | null> {
 93	    const result = await this.pool.query<AccountRow>(
 94	      `SELECT identity_id, login_name, password_hash, nickname, display_name, created_at
 95	       FROM accounts WHERE login_name = $1`,
 96	      [loginName],
 97	    );
 98	    return result.rows[0] ? account(result.rows[0]) : null;
 99	  }
100	
101	  createSession(identityId: string, session: NewAccountSession): Promise<void> {
102	    return insertSession(this.pool, identityId, session);
103	  }
104	
105	  async resolveSession(
106	    tokenHash: string,
107	    now: number,
108	    nextExpiresAt: number,
109	  ): Promise<AccountRecord | null> {
110	    const result = await this.pool.query<AccountRow>(
111	      `UPDATE account_sessions AS sessions
112	       SET expires_at = $3, last_used_at = $2
113	       FROM accounts
114	       WHERE sessions.token_hash = $1
115	         AND sessions.identity_id = accounts.identity_id
116	         AND sessions.expires_at > $2
117	       RETURNING accounts.identity_id, accounts.login_name, accounts.password_hash,
118	                 accounts.nickname, accounts.display_name, accounts.created_at`,
119	      [tokenHash, new Date(now), new Date(nextExpiresAt)],
120	    );
121	    return result.rows[0] ? account(result.rows[0]) : null;
122	  }
123	
124	  async revokeSession(tokenHash: string): Promise<void> {
125	    await this.pool.query(`DELETE FROM account_sessions WHERE token_hash = $1`, [tokenHash]);
126	  }
127	
128	  async close(): Promise<void> {
129	    await this.pool.end();
130	  }
131	}
  1	import type { GameMode } from '@pokewar/protocol';
  2	import type { Pool } from 'pg';
  3	import { ratingTier } from './glicko2.js';
  4	import type { RankedEntry, RatingRepository, StoredRating } from './ratingRepository.js';
  5	
  6	interface RatingRow {
  7	  readonly identity_id: string;
  8	  readonly mode: GameMode;
  9	  readonly rating: number;
 10	  readonly deviation: number;
 11	  readonly volatility: number;
 12	  readonly ranked_games: number;
 13	  readonly wins: number;
 14	  readonly losses: number;
 15	}
 16	interface RankedRow extends RatingRow {
 17	  readonly display_name: string;
 18	  readonly rank: string | number;
 19	}
 20	function stored(row: RatingRow): StoredRating {
 21	  return {
 22	    identityId: row.identity_id,
 23	    mode: row.mode,
 24	    rating: row.rating,
 25	    deviation: row.deviation,
 26	    volatility: row.volatility,
 27	    rankedGames: row.ranked_games,
 28	    wins: row.wins,
 29	    losses: row.losses,
 30	  };
 31	}
 32	function entry(row: RankedRow): RankedEntry {
 33	  return {
 34	    ...stored(row),
 35	    displayName: row.display_name,
 36	    rank: Number(row.rank),
 37	    tier: ratingTier(row.rating),
 38	  };
 39	}
 40	
 41	export class PostgresRatingRepository implements RatingRepository {
 42	  constructor(private readonly pool: Pool) {}
 43	  async ensureAccount(identityId: string, displayName: string): Promise<void> {
 44	    void displayName;
 45	    await this.pool.query(
 46	      `INSERT INTO account_ratings (
 47	         identity_id, mode, rating, deviation, volatility, ranked_games, wins, losses
 48	       ) VALUES
 49	         ($1, 'normal', 1500, 350, 0.06, 0, 0, 0),
 50	         ($1, 'quick', 1500, 350, 0.06, 0, 0, 0)
 51	       ON CONFLICT (identity_id, mode) DO NOTHING`,
 52	      [identityId],
 53	    );
 54	  }
 55	  async getForIdentity(identityId: string): Promise<readonly StoredRating[]> {
 56	    const result = await this.pool.query<RatingRow>(
 57	      `SELECT identity_id, mode, rating, deviation, volatility, ranked_games, wins, losses
 58	       FROM account_ratings WHERE identity_id = $1 ORDER BY mode`,
 59	      [identityId],
 60	    );
 61	    return result.rows.map(stored);
 62	  }
 63	  async leaderboard(
 64	    mode: GameMode,
 65	    identityId: string | null,
 66	  ): Promise<{ entries: readonly RankedEntry[]; self: RankedEntry | null }> {
 67	    const result = await this.pool.query<RankedRow>(
 68	      `WITH ranked AS (
 69	         SELECT ratings.*, accounts.display_name,
 70	                ROW_NUMBER() OVER (ORDER BY rating DESC, ranked_games DESC, ratings.identity_id ASC) AS rank
 71	         FROM account_ratings AS ratings
 72	         JOIN accounts ON accounts.identity_id = ratings.identity_id
 73	         WHERE mode = $1 AND ranked_games >= 5
 74	       )
 75	       SELECT * FROM ranked WHERE rank <= 10 OR identity_id = $2 ORDER BY rank`,
 76	      [mode, identityId],
 77	    );
 78	    const values = result.rows.map(entry);
 79	    return {
 80	      entries: values.filter((value) => value.rank <= 10),
 81	      self: identityId ? (values.find((value) => value.identityId === identityId) ?? null) : null,
 82	    };
 83	  }
 84	  async close(): Promise<void> {
 85	    await this.pool.end();
 86	  }
 87	}
  1	import type { GameMode } from '@pokewar/protocol';
  2	import { ratingTier, type GlickoRating, type RatingTier } from './glicko2.js';
  3	
  4	export interface StoredRating extends GlickoRating {
  5	  readonly identityId: string;
  6	  readonly mode: GameMode;
  7	  readonly rankedGames: number;
  8	  readonly wins: number;
  9	  readonly losses: number;
 10	}
 11	export interface RankedEntry {
 12	  readonly identityId: string;
 13	  readonly displayName: string;
 14	  readonly rating: number;
 15	  readonly rankedGames: number;
 16	  readonly wins: number;
 17	  readonly losses: number;
 18	  readonly rank: number;
 19	  readonly tier: RatingTier;
 20	}
 21	export interface RatingRepository {
 22	  ensureAccount(identityId: string, displayName: string): Promise<void>;
 23	  getForIdentity(identityId: string): Promise<readonly StoredRating[]>;
 24	  leaderboard(
 25	    mode: GameMode,
 26	    identityId: string | null,
 27	  ): Promise<{ entries: readonly RankedEntry[]; self: RankedEntry | null }>;
 28	  close(): Promise<void>;
 29	}
 30	
 31	export class MemoryRatingRepository implements RatingRepository {
 32	  readonly #ratings = new Map<string, StoredRating>();
 33	  readonly #names = new Map<string, string>();
 34	  seed(displayName: string, rating: StoredRating): void {
 35	    this.#names.set(rating.identityId, displayName);
 36	    this.#ratings.set(`${rating.identityId}:${rating.mode}`, rating);
 37	  }
 38	  ensureAccount(identityId: string, displayName: string): Promise<void> {
 39	    this.#names.set(identityId, displayName);
 40	    for (const mode of ['normal', 'quick'] as const) {
 41	      const key = `${identityId}:${mode}`;
 42	      if (!this.#ratings.has(key)) {
 43	        this.#ratings.set(key, {
 44	          identityId,
 45	          mode,
 46	          rating: 1500,
 47	          deviation: 350,
 48	          volatility: 0.06,
 49	          rankedGames: 0,
 50	          wins: 0,
 51	          losses: 0,
 52	        });
 53	      }
 54	    }
 55	    return Promise.resolve();
 56	  }
 57	  getForIdentity(identityId: string): Promise<readonly StoredRating[]> {
 58	    return Promise.resolve(
 59	      [...this.#ratings.values()].filter((value) => value.identityId === identityId),
 60	    );
 61	  }
 62	  leaderboard(
 63	    mode: GameMode,
 64	    identityId: string | null,
 65	  ): Promise<{ entries: readonly RankedEntry[]; self: RankedEntry | null }> {
 66	    const ranked = [...this.#ratings.values()]
 67	      .filter((value) => value.mode === mode && value.rankedGames >= 5)
 68	      .sort(
 69	        (a, b) =>
 70	          b.rating - a.rating ||
 71	          b.rankedGames - a.rankedGames ||
 72	          a.identityId.localeCompare(b.identityId),
 73	      )
 74	      .map((value, index): RankedEntry => ({
 75	        ...value,
 76	        displayName: this.#names.get(value.identityId) ?? 'unknown',
 77	        rank: index + 1,
 78	        tier: ratingTier(value.rating),
 79	      }));
 80	    return Promise.resolve({
 81	      entries: ranked.slice(0, 10),
 82	      self: identityId ? (ranked.find((entry) => entry.identityId === identityId) ?? null) : null,
 83	    });
 84	  }
 85	  close(): Promise<void> {
 86	    this.#ratings.clear();
 87	    this.#names.clear();
 88	    return Promise.resolve();
 89	  }
 90	}

