 44	  async register(
 45	    record: AccountRecord,
 46	    session: NewAccountSession,
 47	  ): Promise<RegisterAccountResult> {
 48	    const client = await this.pool.connect();
 49	    try {
 50	      await client.query('BEGIN');
 51	      const inserted = await client.query(
 52	        `INSERT INTO accounts (identity_id, login_name, password_hash, nickname, display_name, created_at)
 53	         VALUES ($1, $2, $3, $4, $5, $6)
 54	         ON CONFLICT DO NOTHING RETURNING identity_id`,
 55	        [
 56	          record.identityId,
 57	          record.loginName,
 58	          record.passwordHash,
 59	          record.nickname,
 60	          record.displayName,
 61	          new Date(record.createdAt),
 62	        ],
 63	      );
 64	      if (inserted.rowCount !== 1) {
 65	        const existing = await client.query<{ identity_id: string; login_name: string }>(
 66	          `SELECT identity_id, login_name FROM accounts WHERE identity_id = $1 OR login_name = $2`,
 67	          [record.identityId, record.loginName],
 68	        );
 69	        await client.query('ROLLBACK');
 70	        return existing.rows.some((row) => row.identity_id === record.identityId)
 71	          ? 'identity-registered'
 72	          : 'login-taken';
 73	      }
 74	      for (const mode of ['normal', 'quick'] as const) {
 75	        await client.query(
 76	          `INSERT INTO account_ratings (identity_id, mode, rating, deviation, volatility, ranked_games, wins, losses)
 77	           VALUES ($1, $2, 1500, 350, 0.06, 0, 0, 0)`,
 78	          [record.identityId, mode],
 79	        );
 80	      }
 81	      await insertSession(client, record.identityId, session);
 82	      await client.query('COMMIT');
 83	      return 'created';
 84	    } catch (error) {
 85	      await client.query('ROLLBACK');
 86	      throw error;
 87	    } finally {
 88	      client.release();
 89	    }
 90	  }
 91	
 92	  async findByLoginName(loginName: string): Promise<AccountRecord | null> {
 93	    const result = await this.pool.query<AccountRow>(
 94	      `SELECT identity_id, login_name, password_hash, nickname, display_name, created_at
 95	       FROM accounts WHERE login_name = $1`,
 96	      [loginName],
 97	    );
 98	    return result.rows[0] ? account(result.rows[0]) : null;
 99	  }
100	
101	  createSession(identityId: string, session: NewAccountSession): Promise<void> {
102	    return insertSession(this.pool, identityId, session);
103	  }
104	
105	  async resolveSession(
106	    tokenHash: string,
107	    now: number,
108	    nextExpiresAt: number,
109	  ): Promise<AccountRecord | null> {
110	    const result = await this.pool.query<AccountRow>(
111	      `UPDATE account_sessions AS sessions
112	       SET expires_at = $3, last_used_at = $2
113	       FROM accounts
114	       WHERE sessions.token_hash = $1
115	         AND sessions.identity_id = accounts.identity_id
116	         AND sessions.expires_at > $2
117	       RETURNING accounts.identity_id, accounts.login_name, accounts.password_hash,
118	                 accounts.nickname, accounts.display_name, accounts.created_at`,
119	      [tokenHash, new Date(now), new Date(nextExpiresAt)],
120	    );
121	    return result.rows[0] ? account(result.rows[0]) : null;
122	  }
123	
124	  async revokeSession(tokenHash: string): Promise<void> {
125	    await this.pool.query(`DELETE FROM account_sessions WHERE token_hash = $1`, [tokenHash]);
126	  }
127	
128	  async close(): Promise<void> {
129	    await this.pool.end();
130	  }
131	}
