 31	export class MemoryRatingRepository implements RatingRepository {
 32	  readonly #ratings = new Map<string, StoredRating>();
 33	  readonly #names = new Map<string, string>();
 34	  seed(displayName: string, rating: StoredRating): void {
 35	    this.#names.set(rating.identityId, displayName);
 36	    this.#ratings.set(`${rating.identityId}:${rating.mode}`, rating);
 37	  }
 38	  ensureAccount(identityId: string, displayName: string): Promise<void> {
 39	    this.#names.set(identityId, displayName);
 40	    for (const mode of ['normal', 'quick'] as const) {
 41	      const key = `${identityId}:${mode}`;
 42	      if (!this.#ratings.has(key)) {
 43	        this.#ratings.set(key, {
 44	          identityId,
 45	          mode,
 46	          rating: 1500,
 47	          deviation: 350,
 48	          volatility: 0.06,
 49	          rankedGames: 0,
 50	          wins: 0,
 51	          losses: 0,
 52	        });
 53	      }
 54	    }
 55	    return Promise.resolve();
 56	  }
 57	  getForIdentity(identityId: string): Promise<readonly StoredRating[]> {
 58	    return Promise.resolve(
 59	      [...this.#ratings.values()].filter((value) => value.identityId === identityId),
 60	    );
 61	  }
 62	  leaderboard(
 63	    mode: GameMode,
 64	    identityId: string | null,
 65	  ): Promise<{ entries: readonly RankedEntry[]; self: RankedEntry | null }> {
 66	    const ranked = [...this.#ratings.values()]
 67	      .filter((value) => value.mode === mode && value.rankedGames >= 5)
 68	      .sort(
 69	        (a, b) =>
 70	          b.rating - a.rating ||
 71	          b.rankedGames - a.rankedGames ||
 72	          a.identityId.localeCompare(b.identityId),
 73	      )
 74	      .map((value, index): RankedEntry => ({
 75	        ...value,
 76	        displayName: this.#names.get(value.identityId) ?? 'unknown',
 77	        rank: index + 1,
 78	        tier: ratingTier(value.rating),
 79	      }));
 80	    return Promise.resolve({
 81	      entries: ranked.slice(0, 10),
 82	      self: identityId ? (ranked.find((entry) => entry.identityId === identityId) ?? null) : null,
 83	    });
 84	  }
 85	  close(): Promise<void> {
 86	    this.#ratings.clear();
 87	    this.#names.clear();
 88	    return Promise.resolve();
 89	  }
 90	}

