  1	import type { GameMode } from '@pokewar/protocol';
  2	import type { MatchProposal, QueueEntry } from './model.js';
  3	import type { MatchmakingStore } from './matchmakingStore.js';
  4	
  5	const STATE_TTL_SECONDS = 60 * 60;
  6	
  7	export interface RedisMatchmakingClient {
  8	  get(key: string): Promise<string | null>;
  9	  set(key: string, value: string, options?: { EX?: number }): Promise<unknown>;
 10	  del(keys: string | string[]): Promise<number>;
 11	  mGet(keys: string[]): Promise<(string | null)[]>;
 12	  zAdd(key: string, members: { score: number; value: string }[]): Promise<number>;
 13	  zRem(key: string, members: string[]): Promise<number>;
 14	  zRange(key: string, start: number, stop: number): Promise<string[]>;
 15	  zRangeByScore(
 16	    key: string,
 17	    min: number,
 18	    max: number,
 19	    options?: { LIMIT?: { offset: number; count: number } },
 20	  ): Promise<string[]>;
 21	}
 22	
 23	export class RedisMatchmakingStore implements MatchmakingStore {
 24	  constructor(
 25	    private readonly client: RedisMatchmakingClient,
 26	    private readonly prefix: string,
 27	  ) {}
 28	
 29	  async getEntry(identityId: string): Promise<QueueEntry | null> {
 30	    const value = await this.client.get(this.entryKey(identityId));
 31	    return value ? (JSON.parse(value) as QueueEntry) : null;
 32	  }
 33	
 34	  async enqueue(entry: QueueEntry): Promise<'queued' | 'already-active'> {
 35	    if (
 36	      (await this.client.get(this.entryKey(entry.identity.id))) ||
 37	      (await this.client.get(this.identityProposalKey(entry.identity.id)))
 38	    ) {
 39	      return 'already-active';
 40	    }
 41	    await this.client.set(this.entryKey(entry.identity.id), JSON.stringify(entry), {
 42	      EX: STATE_TTL_SECONDS,
 43	    });
 44	    await this.client.zAdd(this.queueKey(entry.mode), [
 45	      { score: entry.enqueuedAt, value: entry.identity.id },
 46	    ]);
 47	    return 'queued';
 48	  }
 49	
 50	  async removeEntry(identityId: string): Promise<void> {
 51	    const entry = await this.getEntry(identityId);
 52	    if (entry) await this.client.zRem(this.queueKey(entry.mode), [identityId]);
 53	    await this.client.del(this.entryKey(identityId));
 54	  }
 55	
 56	  async queuedEntries(limit: number): Promise<readonly QueueEntry[]> {
 57	    const entries = [
 58	      ...(await this.entriesForMode('normal')),
 59	      ...(await this.entriesForMode('quick')),
 60	    ];
 61	    return entries
 62	      .sort(
 63	        (left, right) =>
 64	          left.enqueuedAt - right.enqueuedAt || left.identity.id.localeCompare(right.identity.id),
 65	      )
 66	      .slice(0, limit);
 67	  }
 68	
 69	  async createProposal(proposal: MatchProposal): Promise<boolean> {
 70	    for (const player of proposal.players) {
 71	      if (
 72	        (await this.client.get(this.identityProposalKey(player.identity.id))) ||
 73	        !(await this.client.get(this.entryKey(player.identity.id)))
 74	      ) {
 75	        return false;
 76	      }
 77	    }
 78	    for (const player of proposal.players) await this.removeEntry(player.identity.id);
 79	    await this.saveProposal(proposal);
 80	    return true;
 81	  }
 82	
 83	  async updateProposal(proposal: MatchProposal): Promise<void> {
 84	    const previousValue = await this.client.get(this.proposalKey(proposal.id));
 85	    if (previousValue) {
 86	      const previous = JSON.parse(previousValue) as MatchProposal;
 87	      await this.client.del(
 88	        previous.players.map((player) => this.identityProposalKey(player.identity.id)),
 89	      );
 90	    }
 91	    await this.saveProposal(proposal);
 92	  }
 93	
 94	  async proposals(limit: number): Promise<readonly MatchProposal[]> {
 95	    const ids = await this.client.zRange(this.proposalIndexKey(), 0, limit - 1);
 96	    return this.readProposals(ids);
 97	  }
 98	
 99	  async getProposalFor(identityId: string): Promise<MatchProposal | null> {
100	    const proposalId = await this.client.get(this.identityProposalKey(identityId));
101	    if (!proposalId) return null;
102	    const value = await this.client.get(this.proposalKey(proposalId));
103	    return value ? (JSON.parse(value) as MatchProposal) : null;
104	  }
105	
106	  async acceptProposal(proposalId: string, identityId: string): Promise<MatchProposal | null> {
107	    const value = await this.client.get(this.proposalKey(proposalId));
108	    if (!value) return null;
109	    const proposal = JSON.parse(value) as MatchProposal;
110	    if (!proposal.players.some((player) => player.identity.id === identityId)) return null;
111	    if (proposal.acceptedIds.includes(identityId)) return proposal;
112	    const updated = { ...proposal, acceptedIds: [...proposal.acceptedIds, identityId] };
113	    await this.client.set(this.proposalKey(proposalId), JSON.stringify(updated), {
114	      EX: STATE_TTL_SECONDS,
115	    });
116	    return updated;
117	  }
118	
119	  async deleteProposal(proposalId: string): Promise<void> {
120	    const value = await this.client.get(this.proposalKey(proposalId));
121	    if (value) {
122	      const proposal = JSON.parse(value) as MatchProposal;
123	      await this.client.del(
124	        proposal.players.map((player) => this.identityProposalKey(player.identity.id)),
125	      );
126	    }
127	    await Promise.all([
128	      this.client.del(this.proposalKey(proposalId)),
129	      this.client.zRem(this.dueKey(), [proposalId]),
130	      this.client.zRem(this.proposalIndexKey(), [proposalId]),
131	    ]);
132	  }
133	
134	  async dueProposals(now: number, limit: number): Promise<readonly MatchProposal[]> {
135	    const ids = await this.client.zRangeByScore(this.dueKey(), 0, now, {
136	      LIMIT: { offset: 0, count: limit },
137	    });
138	    return this.readProposals(ids);
139	  }
140	
141	  close(): Promise<void> {
142	    return Promise.resolve();
143	  }
144	
145	  private async saveProposal(proposal: MatchProposal): Promise<void> {
146	    await this.client.set(this.proposalKey(proposal.id), JSON.stringify(proposal), {
147	      EX: STATE_TTL_SECONDS,
148	    });
149	    for (const player of proposal.players) {
150	      await this.client.set(this.identityProposalKey(player.identity.id), proposal.id, {
151	        EX: STATE_TTL_SECONDS,
152	      });
153	    }
154	    const earliest = Math.min(...proposal.players.map((player) => player.enqueuedAt));
155	    await this.client.zAdd(this.proposalIndexKey(), [{ score: earliest, value: proposal.id }]);
156	    await this.client.zRem(this.dueKey(), [proposal.id]);
157	    if (proposal.expiresAt !== null) {
158	      await this.client.zAdd(this.dueKey(), [{ score: proposal.expiresAt, value: proposal.id }]);
159	    }
160	  }
161	
162	  private async readProposals(ids: readonly string[]): Promise<MatchProposal[]> {
163	    if (ids.length === 0) return [];
164	    const values = await this.client.mGet(ids.map((id) => this.proposalKey(id)));
165	    return values.flatMap((value) => (value ? [JSON.parse(value) as MatchProposal] : []));
166	  }
167	
168	  private async entriesForMode(mode: GameMode): Promise<QueueEntry[]> {
169	    const ids = await this.client.zRange(this.queueKey(mode), 0, -1);
170	    if (ids.length === 0) return [];
171	    const values = await this.client.mGet(ids.map((id) => this.entryKey(id)));
172	    return values.flatMap((value) => (value ? [JSON.parse(value) as QueueEntry] : []));
173	  }
174	
175	  private entryKey(identityId: string): string {
176	    return `${this.prefix}match:entry:${identityId}`;
177	  }
178	  private queueKey(mode: GameMode): string {
179	    return `${this.prefix}match:queue:${mode}`;
180	  }
181	  private proposalKey(proposalId: string): string {
182	    return `${this.prefix}match:proposal:${proposalId}`;
183	  }
184	  private identityProposalKey(identityId: string): string {
185	    return `${this.prefix}match:identity:${identityId}`;
186	  }
187	  private dueKey(): string {
188	    return `${this.prefix}match:proposal-due`;
189	  }
190	  private proposalIndexKey(): string {
191	    return `${this.prefix}match:proposal-index`;
192	  }
193	}
  1	import type { MatchmakingState } from '@pokewar/protocol';
  2	import type { RoomState } from '../rooms/model.js';
  3	import type { MatchmakingService } from './matchmakingService.js';
  4	
  5	export interface MatchmakingWorkerCallbacks {
  6	  readonly onUpdates: (updates: ReadonlyMap<string, MatchmakingState>) => void;
  7	  readonly onRoom?: (room: RoomState) => void;
  8	}
  9	
 10	export function startMatchmakingWorker(
 11	  matchmaking: MatchmakingService,
 12	  callbacks: MatchmakingWorkerCallbacks,
 13	  intervalMs = 1_000,
 14	): () => void {
 15	  let running = false;
 16	  const run = async () => {
 17	    if (running) return;
 18	    running = true;
 19	    try {
 20	      const result = await matchmaking.recover(Date.now());
 21	      if (result.ok) {
 22	        callbacks.onUpdates(result.updates);
 23	        for (const room of result.rooms ?? []) callbacks.onRoom?.(room);
 24	      }
 25	    } catch (error) {
 26	      console.error('[matchmaking-worker]', error);
 27	    } finally {
 28	      running = false;
 29	    }
 30	  };
 31	  const timer = setInterval(() => void run(), intervalMs);
 32	  timer.unref();
 33	  void run();
 34	  return () => clearInterval(timer);
 35	}

