  1	import type { RoomState } from '../rooms/model.js';
  2	import type { RoomService } from '../rooms/roomService.js';
  3	import type { DeadlineStore } from './deadlineStore.js';
  4	
  5	const POLL_INTERVAL_MS = 250;
  6	const CLAIM_LIMIT = 64;
  7	
  8	export interface DeadlineWorkerOptions {
  9	  readonly pollIntervalMs?: number;
 10	  readonly claimLimit?: number;
 11	  readonly now?: () => number;
 12	  readonly onRoomUpdated?: (room: RoomState) => void;
 13	}
 14	
 15	export interface DeadlineWorker {
 16	  runOnce(): Promise<number>;
 17	  stop(): void;
 18	}
 19	
 20	export function startDeadlineWorker(
 21	  deadlines: DeadlineStore,
 22	  rooms: RoomService,
 23	  options: DeadlineWorkerOptions = {},
 24	): DeadlineWorker {
 25	  const now = options.now ?? Date.now;
 26	  const limit = options.claimLimit ?? CLAIM_LIMIT;
 27	  let running = false;
 28	  let stopped = false;
 29	
 30	  const runOnce = async (): Promise<number> => {
 31	    if (running || stopped) return 0;
 32	    running = true;
 33	    let processed = 0;
 34	    try {
 35	      const currentTime = now();
 36	      const tasks = await deadlines.claimDue(currentTime, limit);
 37	      for (const task of tasks) {
 38	        try {
 39	          const result = await rooms.processDeadline(task, currentTime);
 40	          if (result.ok && result.value) options.onRoomUpdated?.(result.value);
 41	        } catch (error) {
 42	          console.error('[deadline-worker:task]', task.id, error);
 43	          continue;
 44	        }
 45	        await deadlines.remove(task);
 46	        processed += 1;
 47	      }
 48	      return processed;
 49	    } finally {
 50	      running = false;
 51	    }
 52	  };
 53	
 54	  const timer = setInterval(() => {
 55	    void runOnce().catch((error: unknown) => console.error('[deadline-worker:scan]', error));
 56	  }, options.pollIntervalMs ?? POLL_INTERVAL_MS);
 57	  timer.unref();
 58	  void runOnce().catch((error: unknown) => console.error('[deadline-worker:startup]', error));
 59	
 60	  return {
 61	    runOnce,
 62	    stop() {
 63	      stopped = true;
 64	      clearInterval(timer);
 65	    },
 66	  };
 67	}
  1	import { deadlineScore, type DeadlineTask } from './deadline.js';
  2	import type { DeadlineStore } from './deadlineStore.js';
  3	
  4	export interface RedisDeadlineClient {
  5	  sMembers(key: string): Promise<string[]>;
  6	  del(key: string): Promise<number>;
  7	  sAdd(key: string, members: string[]): Promise<number>;
  8	  zAdd(key: string, members: { score: number; value: string }[]): Promise<number>;
  9	  zRem(key: string, members: string[]): Promise<number>;
 10	  zRangeByScore(
 11	    key: string,
 12	    min: number,
 13	    max: number,
 14	    options: { LIMIT: { offset: number; count: number } },
 15	  ): Promise<string[]>;
 16	}
 17	
 18	export class RedisDeadlineStore implements DeadlineStore {
 19	  constructor(
 20	    private readonly client: RedisDeadlineClient,
 21	    private readonly prefix: string,
 22	  ) {}
 23	
 24	  async replaceRoom(roomId: string, tasks: readonly DeadlineTask[]): Promise<void> {
 25	    const roomKey = this.roomKey(roomId);
 26	    const oldMembers = await this.client.sMembers(roomKey);
 27	    if (oldMembers.length > 0) await this.client.zRem(this.deadlineKey(), oldMembers);
 28	    await this.client.del(roomKey);
 29	    if (tasks.length === 0) return;
 30	    const values = tasks.map((task) => JSON.stringify(task));
 31	    await this.client.zAdd(
 32	      this.deadlineKey(),
 33	      tasks.map((task, index) => ({ score: deadlineScore(task), value: values[index] ?? '' })),
 34	    );
 35	    await this.client.sAdd(roomKey, values);
 36	  }
 37	
 38	  async claimDue(now: number, limit: number): Promise<readonly DeadlineTask[]> {
 39	    const values = await this.client.zRangeByScore(this.deadlineKey(), 0, now * 10 + 9, {
 40	      LIMIT: { offset: 0, count: limit },
 41	    });
 42	    return values.map((value) => JSON.parse(value) as DeadlineTask);
 43	  }
 44	
 45	  async remove(task: DeadlineTask): Promise<void> {
 46	    await this.client.zRem(this.deadlineKey(), [JSON.stringify(task)]);
 47	  }
 48	
 49	  close(): Promise<void> {
 50	    return Promise.resolve();
 51	  }
 52	
 53	  private deadlineKey(): string {
 54	    return `${this.prefix}deadlines`;
 55	  }
 56	
 57	  private roomKey(roomId: string): string {
 58	    return `${this.prefix}deadline-room:${roomId}`;
 59	  }
 60	}
  1	import type { GameCommand, GameState } from '@pokewar/domain';
  2	
  3	type SystemCommand = Extract<GameCommand, { readonly kind: `system:${string}` }>;
  4	import type { RoomState } from '../rooms/model.js';
  5	
  6	export type DeadlineKind = 'disconnect' | 'rescue' | 'starter' | 'replacement' | 'turn';
  7	
  8	export interface DeadlineTask {
  9	  readonly id: string;
 10	  readonly roomId: string;
 11	  readonly kind: DeadlineKind;
 12	  readonly playerId: string;
 13	  readonly dueAt: number;
 14	  readonly gameVersion: number;
 15	}
 16	
 17	const PRIORITY: Readonly<Record<DeadlineKind, number>> = {
 18	  disconnect: 0,
 19	  rescue: 1,
 20	  starter: 2,
 21	  replacement: 2,
 22	  turn: 3,
 23	};
 24	
 25	export function deadlineScore(task: DeadlineTask): number {
 26	  return task.dueAt * 10 + PRIORITY[task.kind];
 27	}
 28	
 29	function task(
 30	  roomId: string,
 31	  kind: DeadlineKind,
 32	  playerId: string,
 33	  dueAt: number,
 34	  gameVersion: number,
 35	): DeadlineTask {
 36	  return {
 37	    id: `${roomId}|${kind}|${playerId}|${String(dueAt)}|${String(gameVersion)}`,
 38	    roomId,
 39	    kind,
 40	    playerId,
 41	    dueAt,
 42	    gameVersion,
 43	  };
 44	}
 45	
 46	export function extractDeadlines(room: RoomState): readonly DeadlineTask[] {
 47	  const game = room.game;
 48	  if (!game || game.phase === 'GAME_OVER') return [];
 49	  const tasks: DeadlineTask[] = [];
 50	  for (const player of game.players) {
 51	    if (!player.eliminated && player.disconnectDeadline !== null) {
 52	      tasks.push(task(room.id, 'disconnect', player.id, player.disconnectDeadline, game.version));
 53	    }
 54	  }
 55	  if (game.phase === 'SELECTING_STARTER') {
 56	    for (const deadline of game.starterDeadlines) {
 57	      const player = game.players.find((candidate) => candidate.id === deadline.playerId);
 58	      if (player?.activeCharacterId === null) {
 59	        tasks.push(task(room.id, 'starter', player.id, deadline.at, game.version));
 60	      }
 61	    }
 62	  }
 63	  if (game.phase === 'WAITING_FOR_JOKER' && game.pendingDeath) {
 64	    const playerId = game.pendingDeath.rescueQueue[game.pendingDeath.rescueIndex];
 65	    if (playerId) {
 66	      tasks.push(task(room.id, 'rescue', playerId, game.pendingDeath.rescueDeadline, game.version));
 67	    }
 68	  }
 69	  if (
 70	    game.phase === 'SELECTING_REPLACEMENT' &&
 71	    game.pendingDeath?.replacementDeadline !== null &&
 72	    game.pendingDeath !== null
 73	  ) {
 74	    tasks.push(
 75	      task(
 76	        room.id,
 77	        'replacement',
 78	        game.pendingDeath.victimPlayerId,
 79	        game.pendingDeath.replacementDeadline,
 80	        game.version,
 81	      ),
 82	    );
 83	  }
 84	  if (game.phase === 'PLAYING' && game.currentPlayerId && game.turnDeadline !== null) {
 85	    tasks.push(task(room.id, 'turn', game.currentPlayerId, game.turnDeadline, game.version));
 86	  }
 87	  return tasks.sort((left, right) => deadlineScore(left) - deadlineScore(right));
 88	}
 89	
 90	export function deadlineCommand(taskValue: DeadlineTask, now: number): SystemCommand {
 91	  const base = {
 92	    actionId: `deadline:${taskValue.id}`,
 93	    expectedVersion: taskValue.gameVersion,
 94	    playerId: taskValue.playerId,
 95	    now,
 96	  };
 97	  switch (taskValue.kind) {
 98	    case 'disconnect':
 99	      return { ...base, kind: 'system:disconnect-timeout' };
100	    case 'rescue':
101	      return { ...base, kind: 'system:rescue-offer-timeout' };
102	    case 'starter':
103	      return { ...base, kind: 'system:starter-timeout' };
104	    case 'replacement':
105	      return { ...base, kind: 'system:replacement-timeout' };
106	    case 'turn':
107	      return { ...base, kind: 'system:turn-timeout' };
108	  }
109	}
110	
111	export function gameForDeadline(room: RoomState, taskValue: DeadlineTask): GameState | null {
112	  return room.game?.version === taskValue.gameVersion ? room.game : null;
113	}

