105	      return { ...base, kind: 'system:replacement-timeout' };
106	    case 'turn':
107	      return { ...base, kind: 'system:turn-timeout' };
108	  }
109	}
110	
111	export function gameForDeadline(room: RoomState, taskValue: DeadlineTask): GameState | null {
112	  return room.game?.version === taskValue.gameVersion ? room.game : null;
113	}

