  1	import type { GameMode, MatchSize, MatchmakingState } from '@pokewar/protocol';
  2	import { randomBytes, randomUUID } from 'node:crypto';
  3	import type { GuestIdentity } from '../identity/guest.js';
  4	import type { RatingRepository } from '../rating/ratingRepository.js';
  5	import type { RoomLockAdapter } from '../rooms/lock.js';
  6	import type { RoomMembershipStore } from '../rooms/membershipStore.js';
  7	import type { RoomState } from '../rooms/model.js';
  8	import type { RoomService } from '../rooms/roomService.js';
  9	import {
 10	  eligibleForSize,
 11	  eligibleSizes,
 12	  groupRatingCompatible,
 13	  rankedProposal,
 14	  type MatchProposal,
 15	  type QueueEntry,
 16	} from './model.js';
 17	import type { MatchmakingStore } from './matchmakingStore.js';
 18	
 19	const CONFIRMATION_MS = 15_000;
 20	const SCAN_LIMIT = 512;
 21	
 22	export type MatchmakingResult =
 23	  | {
 24	      readonly ok: true;
 25	      readonly updates: ReadonlyMap<string, MatchmakingState>;
 26	      readonly rooms?: readonly RoomState[];
 27	    }
 28	  | {
 29	      readonly ok: false;
 30	      readonly code:
 31	        | 'MATCHMAKING_ALREADY_ACTIVE'
 32	        | 'MATCHMAKING_NOT_ACTIVE'
 33	        | 'MATCHMAKING_PROPOSAL_MISMATCH'
 34	        | 'MATCHMAKING_CONFIRMATION_EXPIRED'
 35	        | 'MATCHMAKING_ROOM_CONFLICT';
 36	    };
 37	
 38	function stateForProposal(proposal: MatchProposal, identityId: string): MatchmakingState {
 39	  if (proposal.expiresAt === null) {
 40	    return {
 41	      status: 'queued',
 42	      mode: proposal.mode,
 43	      targetSize: proposal.finalSize,
 44	      allowFallback: false,
 45	      enqueuedAt: Math.min(...proposal.players.map((player) => player.enqueuedAt)),
 46	      groupedPlayers: proposal.players.length,
 47	    };
 48	  }
 49	  return {
 50	    status: 'confirming',
 51	    proposalId: proposal.id,
 52	    mode: proposal.mode,
 53	    finalSize: proposal.finalSize,
 54	    ranked: rankedProposal(proposal),
 55	    expiresAt: proposal.expiresAt,
 56	    accepted: proposal.acceptedIds.includes(identityId),
 57	  };
 58	}
 59	
 60	export class MatchmakingService {
 61	  constructor(
 62	    private readonly store: MatchmakingStore,
 63	    private readonly lock: RoomLockAdapter,
 64	    private readonly rooms: RoomService,
 65	    private readonly memberships: RoomMembershipStore,
 66	    private readonly ratings: RatingRepository,
 67	  ) {}
 68	
 69	  async runIfIdle<T>(
 70	    identityId: string,
 71	    task: () => Promise<T>,
 72	  ): Promise<{ readonly ok: true; readonly value: T } | { readonly ok: false }> {
 73	    return this.lock.run('matchmaking', async () => {
 74	      if (
 75	        (await this.store.getEntry(identityId)) ||
 76	        (await this.store.getProposalFor(identityId))
 77	      ) {
 78	        return { ok: false };
 79	      }
 80	      return { ok: true, value: await task() };
 81	    });
 82	  }
 83	
 84	  async state(identityId: string): Promise<MatchmakingState> {
 85	    const proposal = await this.store.getProposalFor(identityId);
 86	    if (proposal) return stateForProposal(proposal, identityId);
 87	    const entry = await this.store.getEntry(identityId);
 88	    return entry ? this.queuedState(entry, 1) : { status: 'idle' };
 89	  }
 90	
 91	  async enqueue(
 92	    identity: GuestIdentity,
 93	    mode: GameMode,
 94	    targetSize: MatchSize,
 95	    allowFallback: boolean,
 96	    now: number,
 97	  ): Promise<MatchmakingResult> {
 98	    return this.lock.run('matchmaking', async () => {
 99	      if (await this.memberships.get(identity.id)) {
100	        return { ok: false, code: 'MATCHMAKING_ROOM_CONFLICT' };
101	      }
102	      if (
103	        (await this.store.getEntry(identity.id)) ||
104	        (await this.store.getProposalFor(identity.id))
105	      ) {
106	        return { ok: false, code: 'MATCHMAKING_ALREADY_ACTIVE' };
107	      }
108	      const entry: QueueEntry = {
109	        identity,
110	        mode,
111	        requestedSize: targetSize,
112	        allowFallback,
113	        rating: await this.matchingRating(identity, mode),
114	        enqueuedAt: now,
115	      };
116	      await this.store.enqueue(entry);
117	      const updates = await this.formGroups(now);
118	      if (!updates.has(identity.id)) updates.set(identity.id, this.queuedState(entry, 1));
119	      return { ok: true, updates };
120	    });
121	  }
122	
123	  async cancel(identityId: string, now: number): Promise<MatchmakingResult> {
124	    return this.lock.run('matchmaking', async () => {
125	      const entry = await this.store.getEntry(identityId);
126	      if (entry) {
127	        await this.store.removeEntry(identityId);
128	        return { ok: true, updates: new Map([[identityId, { status: 'idle' }]]) };
129	      }
130	      const proposal = await this.store.getProposalFor(identityId);
131	      if (!proposal) return { ok: false, code: 'MATCHMAKING_NOT_ACTIVE' };
132	      const remaining = proposal.players.filter((player) => player.identity.id !== identityId);
133	      await this.store.deleteProposal(proposal.id);
134	      const updates = new Map<string, MatchmakingState>([[identityId, { status: 'idle' }]]);
135	      if (remaining.length > 0) {
136	        const retained: MatchProposal = {
137	          ...proposal,
138	          players: remaining,
139	          acceptedIds: [],
140	          expiresAt: null,
141	        };
142	        await this.store.updateProposal(retained);
143	        for (const player of remaining) {
144	          updates.set(player.identity.id, stateForProposal(retained, player.identity.id));
145	        }
146	      }
147	      const formed = await this.formGroups(now);
148	      for (const [id, state] of formed) updates.set(id, state);
149	      return { ok: true, updates };
150	    });
151	  }
152	
153	  async accept(identityId: string, proposalId: string, now: number): Promise<MatchmakingResult> {
154	    return this.lock.run('matchmaking', async () => {
155	      const proposal = await this.store.getProposalFor(identityId);
156	      if (proposal?.id !== proposalId || proposal.expiresAt === null) {
157	        return { ok: false, code: 'MATCHMAKING_PROPOSAL_MISMATCH' };
158	      }
159	      if (proposal.expiresAt <= now) {
160	        await this.resolveExpiredProposal(proposal, now);
161	        return { ok: false, code: 'MATCHMAKING_CONFIRMATION_EXPIRED' };
162	      }
163	      const updated = await this.store.acceptProposal(proposalId, identityId);
164	      if (!updated) return { ok: false, code: 'MATCHMAKING_PROPOSAL_MISMATCH' };
165	      if (updated.acceptedIds.length < updated.finalSize) {
166	        return { ok: true, updates: this.proposalUpdates(updated) };
167	      }
168	      const room = await this.finalizeProposal(updated, now);
169	      return {
170	        ok: true,
171	        rooms: [room],
172	        updates: new Map(updated.players.map((player) => [player.identity.id, { status: 'idle' }])),
173	      };
174	    });
175	  }
176	
177	  async recover(now: number): Promise<MatchmakingResult> {
178	    return this.lock.run('matchmaking', async () => {
179	      const updates = new Map<string, MatchmakingState>();
180	      const rooms: RoomState[] = [];
181	      for (const proposal of await this.store.dueProposals(now, SCAN_LIMIT)) {
182	        if (proposal.acceptedIds.length === proposal.finalSize) {
183	          rooms.push(await this.finalizeProposal(proposal, now));
184	          for (const player of proposal.players)
185	            updates.set(player.identity.id, { status: 'idle' });
186	        } else {
187	          const resolved = await this.resolveExpiredProposal(proposal, now);
188	          for (const [id, state] of resolved) updates.set(id, state);
189	        }
190	      }
191	      const formed = await this.formGroups(now);
192	      for (const [id, state] of formed) updates.set(id, state);
193	      return { ok: true, updates, ...(rooms.length > 0 ? { rooms } : {}) };
194	    });
195	  }
196	
197	  private async resolveExpiredProposal(
198	    proposal: MatchProposal,
199	    now: number,
200	  ): Promise<ReadonlyMap<string, MatchmakingState>> {
201	    const retainedPlayers = proposal.players.filter((player) =>
202	      proposal.acceptedIds.includes(player.identity.id),
203	    );
204	    await this.store.deleteProposal(proposal.id);
205	    const updates = new Map<string, MatchmakingState>();
206	    for (const player of proposal.players) {
207	      if (!proposal.acceptedIds.includes(player.identity.id)) {
208	        updates.set(player.identity.id, { status: 'idle' });
209	      }
210	    }
211	    if (retainedPlayers.length > 0) {
212	      const retained: MatchProposal = {
213	        ...proposal,
214	        players: retainedPlayers,
215	        acceptedIds: [],
216	        expiresAt: null,
217	      };
218	      await this.store.updateProposal(retained);
219	      for (const player of retainedPlayers) {
220	        updates.set(player.identity.id, stateForProposal(retained, player.identity.id));
221	      }
222	    }
223	    const formed = await this.formGroups(now);
224	    for (const [id, state] of formed) updates.set(id, state);
225	    return updates;
226	  }
227	
228	  private async formGroups(now: number): Promise<Map<string, MatchmakingState>> {
229	    const updates = new Map<string, MatchmakingState>();
230	    await this.fillRetainedGroups(now, updates);
231	    let entries = [...(await this.store.queuedEntries(SCAN_LIMIT))];
232	    for (const seed of entries) {
233	      if (!(await this.store.getEntry(seed.identity.id))) continue;
234	      for (const size of eligibleSizes(seed, now)) {
235	        const group = this.buildGroup(seed, entries, size, now);
236	        if (group.length !== size) continue;
237	        const proposal: MatchProposal = {
238	          id: randomUUID(),
239	          roomId: await this.rooms.allocateRoomId(),
240	          mode: seed.mode,
241	          finalSize: size,
242	          players: group,
243	          acceptedIds: [],
244	          expiresAt: now + CONFIRMATION_MS,
245	        };
246	        if (await this.store.createProposal(proposal)) {
247	          for (const [id, state] of this.proposalUpdates(proposal)) updates.set(id, state);
248	          const ids = new Set(group.map((player) => player.identity.id));
249	          entries = entries.filter((entry) => !ids.has(entry.identity.id));
250	        }
251	        break;
252	      }
253	    }
254	    return updates;
255	  }
256	
257	  private async fillRetainedGroups(
258	    now: number,
259	    updates: Map<string, MatchmakingState>,
260	  ): Promise<void> {
261	    for (const proposal of await this.store.proposals(SCAN_LIMIT)) {
262	      if (proposal.expiresAt !== null || proposal.players.length >= proposal.finalSize) continue;
263	      const queue = await this.store.queuedEntries(SCAN_LIMIT);
264	      const players = [...proposal.players];
265	      for (const candidate of queue) {
266	        if (players.length >= proposal.finalSize) break;
267	        if (
268	          candidate.mode !== proposal.mode ||
269	          !eligibleForSize(candidate, proposal.finalSize, now) ||
270	          !groupRatingCompatible([...players, candidate], now)
271	        ) {
272	          continue;
273	        }
274	        players.push(candidate);
275	        await this.store.removeEntry(candidate.identity.id);
276	      }
277	      const updated: MatchProposal = {
278	        ...proposal,
279	        players,
280	        acceptedIds: [],
281	        expiresAt: players.length === proposal.finalSize ? now + CONFIRMATION_MS : null,
282	      };
283	      await this.store.updateProposal(updated);
284	      for (const [id, state] of this.proposalUpdates(updated)) updates.set(id, state);
285	    }
286	  }
287	
288	  private buildGroup(
289	    seed: QueueEntry,
290	    entries: readonly QueueEntry[],
291	    size: MatchSize,
292	    now: number,
293	  ): QueueEntry[] {
294	    const group: QueueEntry[] = [seed];
295	    for (const candidate of entries) {
296	      if (group.length >= size) break;
297	      if (
298	        candidate.identity.id === seed.identity.id ||
299	        candidate.mode !== seed.mode ||
300	        !eligibleForSize(candidate, size, now) ||
301	        !groupRatingCompatible([...group, candidate], now)
302	      ) {
303	        continue;
304	      }
305	      group.push(candidate);
306	    }
307	    return group;
308	  }
309	
310	  private async finalizeProposal(proposal: MatchProposal, now: number): Promise<RoomState> {
311	    const identities = proposal.players.map((player) => player.identity);
312	    if (identities.length !== proposal.finalSize) throw new Error('MATCHMAKING_GROUP_NOT_FULL');
313	    const room = await this.rooms.createMatchmade(
314	      proposal.roomId,
315	      identities,
316	      proposal.mode,
317	      randomBytes(32).toString('hex'),
318	      now,
319	    );
320	    for (const player of proposal.players) {
321	      await this.memberships.set(player.identity.id, room.id);
322	    }
323	    await this.store.deleteProposal(proposal.id);
324	    return room;
325	  }
326	
327	  private async matchingRating(identity: GuestIdentity, mode: GameMode): Promise<number> {
328	    if (identity.kind !== 'account') return 1500;
329	    await this.ratings.ensureAccount(identity.id, identity.displayName);
330	    const values = await this.ratings.getForIdentity(identity.id);
331	    return values.find((rating) => rating.mode === mode)?.rating ?? 1500;
332	  }
333	
334	  private proposalUpdates(proposal: MatchProposal): ReadonlyMap<string, MatchmakingState> {
335	    return new Map(
336	      proposal.players.map((player) => [
337	        player.identity.id,
338	        stateForProposal(proposal, player.identity.id),
339	      ]),
340	    );
341	  }
342	
343	  private queuedState(entry: QueueEntry, groupedPlayers: number): MatchmakingState {
344	    return {
345	      status: 'queued',
346	      mode: entry.mode,
347	      targetSize: entry.requestedSize,
348	      allowFallback: entry.allowFallback,
349	      enqueuedAt: entry.enqueuedAt,
350	      groupedPlayers,
351	    };
352	  }
353	}

