    43	afterEach(async () => {
    44	  for (const client of clients.splice(0)) client.disconnect();
    45	  if (activeServer) {
    46	    await activeServer.io.close();
    47	    const httpServer = activeServer.httpServer;
    48	    if (httpServer.listening) {
