    55	function firstCookie(value: unknown): string | undefined {
    56	  return Array.isArray(value) && typeof value[0] === 'string' ? value[0] : undefined;
    57	}
    58	
    59	async function guestCookie(server: PokeWarServer): Promise<string> {
    60	  const response = await request(server.app).post('/api/guest/session').send({});
    61	  const cookie = firstCookie(response.headers['set-cookie']);
    62	  if (!cookie) throw new Error('TEST_COOKIE_MISSING');
    63	  return cookie.split(';', 1)[0] ?? cookie;
    64	}
    65	
    66	async function connect(url: string, cookie: string): Promise<Socket> {
    67	  const client = createClient(url, {
    68	    transports: ['websocket'],
    69	    extraHeaders: { Cookie: cookie, Origin: 'http://localhost:5173' },
    70	  });
    71	  clients.push(client);
    72	  await new Promise<void>((resolve, reject) => {
    73	    client.once('connect', () => resolve());
    74	    client.once('connect_error', reject);
    75	  });
    76	  return client;
    77	}
    78	
    79	function emitAck(socket: Socket, event: string, payload: unknown): Promise<unknown> {
    80	  return new Promise((resolve) =>
    81	    socket.emit(event, payload, (response: unknown) => resolve(response)),
    82	  );
    83	}
    84	
    85	function nextGameSnapshot(socket: Socket): Promise<Snapshot> {
    86	  return new Promise((resolve) => {
    87	    const handler = (payload: unknown) => {
